  /* ====================================================================== Platinen aufbauen */
  /* parts: [ref, fp, value, x, y, rot, side]; nets: { NAME: [cls, [pins], extra] } */
  function mk(o, parts, nets) {
    const b = CORE().newBoard(o);
    parts.forEach((p, i) => b.parts.push({ id: 'p' + (i + 1), ref: p[0], fp: p[1], value: p[2], x: p[3], y: p[4], rot: p[5] || 0, side: p[6] || 'top' }));
    b.nets = Object.keys(nets).map(k => { const n = nets[k], r = { name: k, cls: n[0], pins: n[1].slice() }; if (n[2]) Object.assign(r, n[2]); return r; });
    return b;
  }
  const full = (b, layer, net, cl) => ({ id: 'z' + layer.replace(/\W/g, ''), layer, net, poly: [[0.5, 0.5], [b.w - 0.5, 0.5], [b.w - 0.5, b.h - 0.5], [0.5, b.h - 0.5]], clearance: cl || 0.3, thermals: true });
  function planes(b, spec) { b.zones = (b.zones || []).concat(spec.map(s => full(b, s[0], s[1]))); return b; }
  /* eingebackene Verlegung anwenden: t = [Lage, Netz, Breite, [x,y,x,y,...]], v = [x,y,Netz,Durchm,Bohrung], z = [Lage,Netz,Polygon,Abstand] */
  function bakeInto(b, k) {
    const d = BAKE[k]; if (!d) return b;
    b.tracks = (d.t || []).map((t, i) => ({ id: 't' + (i + 1), layer: t[0], net: t[1], w: t[2], pts: t[3].reduce((a, v, j) => { if (j % 2 === 0) a.push([v, t[3][j + 1]]); return a; }, []) }));
    b.vias = (d.v || []).map((v, i) => ({ id: 'v' + (i + 1), x: v[0], y: v[1], net: v[2], dia: v[3], drill: v[4], from: 'F.Cu', to: 'B.Cu' }));
    if (d.z) b.zones = d.z.map((z, i) => ({ id: 'z' + (i + 1), layer: z[0], net: z[1], poly: z[2], clearance: z[3], thermals: true }));
    return b;
  }
  const strip = b => { b.tracks = []; b.vias = []; return b; };

