  const drcOf = (b, o) => { try { return CORE().drc(b, o) || []; } catch (e) { return []; } };
  const errsOf = (b, ign, o) => drcOf(b, o).filter(d => d.severity === 'error' && (!ign || ign.indexOf(d.type) < 0));
  const connOf = b => { try { return CORE().connectivity(b) || { nets: [], unrouted: [], shorts: [] }; } catch (e) { return { nets: [], unrouted: [], shorts: [] }; } };
  const msgs = (list, n) => list.slice(0, n || 2).map(d => d.msg).join(' | ');
  const padMap = b => { const m = {}; try { CORE().padsOf(b).forEach(p => { m[p.ref + '.' + p.n] = p; }); } catch (e) { /* leer */ } return m; };
  const tlen = t => { let s = 0; const p = arr(t.pts); for (let i = 1; i < p.length; i++) s += Math.hypot(p[i][0] - p[i - 1][0], p[i][1] - p[i - 1][1]); return s; };
  const netLen = (b, n) => b.tracks.filter(t => t.net === n).reduce((a, t) => a + tlen(t), 0);
  const polyArea = p => { let s = 0; arr(p).forEach((q, i) => { const r = p[(i + 1) % p.length]; s += q[0] * r[1] - r[0] * q[1]; }); return Math.abs(s) / 2; };
  const isInner = id => /^In\d\.Cu$/.test(id || '');
  const isGndName = n => /^(GND|AGND|DGND|PGND|MASSE|0V)$/i.test(n || '');
  const A = b => (b.answers && typeof b.answers === 'object' ? b.answers : {});

  const lnConn = b => { const c = connOf(b), u = c.unrouted[0]; return L(c.unrouted.length === 0, 'Alle Netze sind verbunden', c.unrouted.length + ' Verbindung(en) fehlen noch' + (u ? ', zum Beispiel im Netz ' + u.net + ' zwischen ' + ((u.a && u.a.pad) || '?') + ' und ' + ((u.b && u.b.pad) || '?') : '') + '. Zieh die Luftlinien mit Leiterbahnen nach (Auto-Weg hilft).'); };
  const lnShort = b => { const c = connOf(b), s = c.shorts[0]; return L(c.shorts.length === 0, 'Keine Kurzschlüsse', s ? 'Kurzschluss zwischen ' + s.netA + ' und ' + s.netB + (s.at ? ' bei (' + f2(s.at.x, 1) + '; ' + f2(s.at.y, 1) + ')' : '') + '.' : ''); };
  const lnDrc = (b, ign) => { const e = errsOf(b, ign); return L(e.length === 0, 'Der DRC meldet keine Fehler', e.length + ' Fehler, zum Beispiel: ' + msgs(e)); };
  const lnRules = b => { const r = b.rules || {}, ok = !(r.clearance < 0.2 - 1e-9) && !(r.minWidth < 0.2 - 1e-9) && !(r.minDrill < 0.3 - 1e-9) && !(r.annular < 0.15 - 1e-9) && !(r.edge < 0.3 - 1e-9); return L(ok, 'Die Entwurfsregeln sind nicht aufgeweicht', 'Du darfst die Regeln nicht lockern, um Fehler zu verstecken (Abstand mindestens 0,2 mm, Bahnbreite mindestens 0,2 mm, Bohrung mindestens 0,3 mm, Restring mindestens 0,15 mm, Randabstand mindestens 0,3 mm).'); };
  const lnParts = (b, ref) => { const a = ref.parts.map(p => p.ref + ':' + p.fp).sort().join(','), c = b.parts.map(p => p.ref + ':' + p.fp).sort().join(','); return L(a === c, 'Alle Bauteile sind noch vorhanden', 'Es fehlen Bauteile oder ein Footprint wurde geändert. Erwartet: ' + ref.parts.map(p => p.ref).join(', ') + '.'); };
  const netKey = n => n.name + '=' + arr(n.pins).slice().sort().join(',');
  const lnNets = (b, ref) => { const a = ref.nets.map(netKey).sort().join(';'), c = b.nets.map(netKey).sort().join(';'); return L(a === c, 'Die Netzliste ist unverändert', 'Die Netzliste kommt aus dem Schaltplan und darf nicht geändert werden.'); };
  const lnVias = (b, max, net) => { const n = b.vias.filter(v => !net || v.net === net).length; return L(n <= max, 'Nicht mehr als ' + max + ' Vias' + (net ? ' im Netz ' + net : ''), 'Du hast ' + n + ' Vias gesetzt. Jeder Lagenwechsel kostet Platz und Geld, setze nur so viele wie nötig.'); };
  /* Standard bei Verlege-Aufgaben: Teile, Netze, Verbindungen, Kurzschlüsse, DRC */
  const routeLines = (b, ref, o) => { o = o || {}; const r = [lnParts(b, ref), lnNets(b, ref), lnConn(b), lnShort(b), lnDrc(b, o.ign)]; if (o.vias != null) r.push(lnVias(b, o.vias)); return r; };

  function roleOf(b, id) {
    const rr = b.layerRoles && b.layerRoles[id]; if (rr) return rr;
    const z = arr(b.zones).filter(q => q && q.layer === id && q.net);
    if (z.length) return isGndName(z[0].net) ? 'gnd' : 'vcc';
    const n = +b.layers;
    if (id === 'In1.Cu') return 'gnd';
    if (n === 4 && id === 'In2.Cu') return 'vcc';
    if (n === 6 && id === 'In4.Cu') return 'vcc';
    return 'signal';
  }
  const zones = (b, net, pred) => arr(b.zones).filter(z => z && z.net === net && (!pred || pred(z.layer)) && arr(z.poly).length >= 3);
  const cover = (b, net, pred) => { const a = zones(b, net, pred).reduce((s, z) => s + polyArea(z.poly), 0); return Math.min(1, a / Math.max(1, b.w * b.h)); };
  const ipcFor = (b, I, layer) => CORE().ipcWidth(I, { oz: isInner(layer) ? (b.inOz || 0.5) : (b.copperOz || 1), rise: 10, external: !isInner(layer) });
  /* Bahnbreite nach IPC je Netz mit Strom prüfen */
  function lnsWidth(b, nets) {
    return nets.map(name => {
      const n = b.nets.find(x => x.name === name), I = n && n.current > 0 ? n.current : 0;
      if (!I) return L(false, 'Netz ' + name + ': Strom ist eingetragen', 'Der Strom des Netzes ' + name + ' fehlt in der Netzliste. Er gehört zur Aufgabe und darf nicht gelöscht werden.');
      const ts = b.tracks.filter(t => t.net === name), bad = ts.filter(t => (+t.w || 0) < ipcFor(b, I, t.layer) - 1e-6);
      return L(ts.length > 0 && bad.length === 0, 'Netz ' + name + ': Bahnen breit genug für ' + f2(I, 1) + ' A', () => ts.length === 0 ? 'Das Netz hat keine Leiterbahnen.' : 'Bahn ' + bad[0].id + ' ist ' + f2(bad[0].w) + ' mm breit, nach IPC-2221 (10 K Erwärmung, ' + f2(b.copperOz || 1, 0) + ' oz) brauchst du mindestens ' + f2(ipcFor(b, I, bad[0].layer)) + ' mm.');
    });
  }

  /* ====================================================================== Platinen-Varianten für die Aufgaben */
  const setW = (b, fn) => { b.tracks.forEach(t => { const w = fn(t); if (w != null) t.w = w; }); return b; };
  const setCur = (b, map) => { b.nets.forEach(n => { if (map[n.name] != null) n.current = map[n.name]; }); return b; };
  const withAnswers = (b, a) => { b.answers = a; return b; };
  /* Säurefallen einbauen: Bahn ti, Segment si, Seite s (+1/-1) */
  function spike(b, ti, si, s) {
    const t = b.tracks[ti], a = t.pts[si], c = t.pts[si + 1], dx = c[0] - a[0], dy = c[1] - a[1], l = Math.hypot(dx, dy), ux = dx / l, uy = dy / l, nx = -uy * s, ny = ux * s;
    const P = (f, h) => [Math.round((a[0] + ux * l * f + nx * h) * 1000) / 1000, Math.round((a[1] + uy * l * f + ny * h) * 1000) / 1000];
    t.pts.splice(si + 1, 0, P(0.7, 0), P(0.45, 1.4), P(0.6, 0));
    return b;
  }
  const ACID = /*ACID_BEGIN*/[[0,0,1],[7,2,1],[12,2,1]]/*ACID_END*/;
  const acidStart = () => { const b = board('exled'); ACID.forEach(a => spike(b, a[0], a[1], a[2])); return b; };
  const reflip = (b, refs) => { b.parts.forEach(p => { if (refs.indexOf(p.ref) >= 0) p.rot = (p.rot + 180) % 360; }); return b; };
  const viasBad = b => { b.vias.forEach(v => { if (v.net === 'N1') { v.dia = 0.5; v.drill = 0.4; } else { v.dia = 0.6; v.drill = 0.2; } }); return b; };
  const mfgStart = () => { const b = board('h2_mfg'); b.rules = Object.assign({}, b.rules, { minWidth: 0.1, clearance: 0.1 }); return b; };
  function snapGrid(b, g, last) {
    const P = CORE().padsOf(b);
    b.parts.forEach(p => { const ps = P.filter(q => q.ref === p.ref); if (!ps.length) return; const q = last ? ps[ps.length - 1] : ps[0]; p.x = Math.round((p.x + Math.round(q.x / g) * g - q.x) * 10000) / 10000; p.y = Math.round((p.y + Math.round(q.y / g) * g - q.y) * 10000) / 10000; });
    return b;
  }
  const repStart = (key, kinds) => { let r = { board: board(key) }; if (REP()) kinds.forEach(k => { const x = REP().inject(r.board, { kind: k[0], seed: k[1] }); if (x && x.board) r = x; }); return r.board; };
  const repSol = b => (REP() ? REP().autoFix(b).board : b);
  const repLines = b => {
    const R = REP(); if (!R) return [L(false, 'Das Reparatur-Modul ist nicht geladen', 'pcbrepair.js fehlt.')];
    const v = R.verify(b), rest = arr(v && v.remaining), sol = b.repair && b.repair.soll, parts = sol ? arr(sol.parts) : [];
    const lost = parts.filter(sp => !b.parts.some(p => p.ref === sp.ref && p.fp === sp.fp));
    return [L(v && v.ok, 'Der Fehler ist gefunden und behoben', rest.length ? 'Noch nicht in Ordnung: ' + rest.slice(0, 2).map(x => x.msg).join(' | ') : 'Die Baugruppe stimmt noch nicht mit dem Soll-Stand überein.'),
      L(lost.length === 0, 'Es fehlt kein Bauteil, das in Ordnung war', 'Du hast ' + (lost[0] ? lost[0].ref : 'ein Bauteil') + ' entfernt. Miss erst, bevor du Bauteile auslötest.'),
      L(!!(b.repair && b.repair.soll), 'Die Platine gehört zur Reparaturaufgabe', 'Die Platine wurde ausgetauscht. Repariere die vorgegebene Baugruppe.')];
  };

  /* ====================================================================== Aufgaben */
  const GERBER = [['.gtl', 'Kupfer oben (F.Cu)'], ['.gbl', 'Kupfer unten (B.Cu)'], ['.gts', 'Lötstopplack oben'], ['.gbs', 'Lötstopplack unten'], ['.gtp', 'Lotpaste oben (Schablone)'], ['.gto', 'Bestückungsdruck oben'], ['.gbo', 'Bestückungsdruck unten'], ['.gm1', 'Platinenumriss'], ['.drl', 'Bohrungen']];
  const gerberSol = () => { const a = {}; GERBER.forEach(g => { a[g[0]] = g[1]; }); return a; };
  const gerberAns = () => GERBER.map(g => ({ k: g[0], label: 'Datei mit Endung ' + g[0], type: 'select', options: GERBER.map(x => [x[1], x[1]]) }));
  const PROF_ANS = [{ k: 'ramp', label: 'Aufheizrate', unit: '°C/s', type: 'num', min: 0.3, max: 8, step: 0.1 }, { k: 'soakTime', label: 'Haltezeit Soak', unit: 's', type: 'num', min: 10, max: 240, step: 5 }, { k: 'soakEnd', label: 'Temperatur am Ende des Soak', unit: '°C', type: 'num', min: 120, max: 230, step: 5 },
    { k: 'peak', label: 'Spitzentemperatur (Peak)', unit: '°C', type: 'num', min: 180, max: 290, step: 1 }, { k: 'tal', label: 'Zeit über 217 °C (Liquidus)', unit: 's', type: 'num', min: 5, max: 150, step: 1 }, { k: 'cool', label: 'Abkühlrate', unit: '°C/s', type: 'num', min: 0.2, max: 8, step: 0.1 }];
  const profOf = a => { const p = {}; PROF_ANS.forEach(f => { p[f.k] = num(a[f.k]); }); return p; };
  const TIP_OPTS = [['meissel', 'Meißelspitze 2,4 mm'], ['kegel', 'Kegelspitze 1,0 mm'], ['fein', 'Feinspitze 0,4 mm'], ['messer', 'Messerspitze 3 mm (zum Schleppen)']];

  const tasks = [
    /* ---------------- Grundlagen */
    { id: 'pb1', lab: 'pcb', cat: 'Grundlagen', title: 'Pads auf das 2,54-mm-Raster legen', level: 2,
      text: 'Stecker, IC, LED, Transistor und Widerstand sind frei auf der Platine verteilt. Verschiebe die Bauteile so, dass alle Pads (nicht die Bauteilmitten!) auf dem 2,54-mm-Raster liegen, gemessen vom linken oberen Platinenrand. Nur dann passen sie später in Lochraster-Fassungen und Stiftleisten. Zeig dir dazu die Pad-Koordinaten an: Bei Bauteilen mit gerader Pinzahl liegt die Mitte zwischen zwei Pins.',
      hint: ['Das Raster bezieht sich auf die Pads. Schau dir an, wie weit Pad 1 vom Bauteilmittelpunkt entfernt ist.', 'Der HDR_1x4 hat Pads bei y = -3,81 / -1,27 / 1,27 / 3,81 mm um die Mitte. Seine Mitte muss also auf einem ungeraden Vielfachen von 1,27 mm liegen, nicht auf dem 2,54-mm-Raster.', 'Schiebe jedes Bauteil so, dass Pad 1 auf einem Rasterpunkt liegt (x und y ein Vielfaches von 2,54). Dann liegen auch alle anderen Pads auf dem Raster, weil ihr Abstand ein Vielfaches von 2,54 mm ist.'],
      start: () => board('rast'), sol: () => snapGrid(board('rast'), 2.54, false),
      check(b) {
        const ref = DEF.rast(), P = padMap(b), out = [lnParts(b, ref)], g = 2.54;
        const on = v => { const q = v / g; return Math.abs(q - Math.round(q)) * g < 0.03; };
        ref.parts.forEach(rp => {
          const pads = Object.keys(P).filter(k => k.split('.')[0] === rp.ref), off = pads.filter(k => !on(P[k].x) || !on(P[k].y));
          const q = off[0] ? P[off[0]] : null;
          out.push(L(pads.length > 0 && off.length === 0, rp.ref + ' (' + rp.fp + '): alle Pads auf dem Raster', () => pads.length === 0 ? 'Das Bauteil fehlt.' : 'Pad ' + off[0].split('.')[1] + ' liegt bei x = ' + f2(q.x) + ' mm, y = ' + f2(q.y) + ' mm. Teilst du durch 2,54, kommt ' + f2(q.x / g) + ' bzw. ' + f2(q.y / g) + ' heraus, das ist nicht ganzzahlig.'));
        });
        out.push(lnDrc(b, ['unconnected']));
        return out;
      } },
    { id: 'pb2', lab: 'pcb', cat: 'Grundlagen', title: 'Footprints für den SMD-Bestücker wählen', level: 1,
      text: 'Die Platine ist mit bedrahteten Bauteilen entworfen, aber der Bestücker verarbeitet nur SMD. Tausche die Footprints: beide Widerstände R1 und R2 auf R0603, den Kondensator C1 auf C0603 und die LED D1 auf LED0603. Die Netzliste bleibt gleich, die Pads müssen weiter zu den Pins passen.',
      hint: ['Jedes Bauteil hat einen Footprint, der die Pads und die Gehäuseform festlegt. Ändere ihn in den Bauteil-Eigenschaften.', 'Die Zahl im Namen ist die Gehäusegröße in Zoll: 0603 = 1,6 x 0,8 mm. R0603 ist ein Widerstand, C0603 ein Kondensator, LED0603 eine LED.', 'R1, R2: R0603. C1: C0603. D1: LED0603. Der Stecker J1 bleibt unverändert.'],
      start: () => board('fp1'),
      sol: () => { const b = board('fp1'), m = { R1: 'R0603', R2: 'R0603', C1: 'C0603', D1: 'LED0603' }; b.parts.forEach(p => { if (m[p.ref]) p.fp = m[p.ref]; }); return b; },
      check(b) {
        const want = { R1: 'R0603', R2: 'R0603', C1: 'C0603', D1: 'LED0603' }, out = [];
        Object.keys(want).forEach(r => { const p = b.parts.find(q => q.ref === r); out.push(L(p && p.fp === want[r], r + ' hat den Footprint ' + want[r], p ? r + ' hat noch ' + p.fp + '. Gefordert ist ' + want[r] + '.' : r + ' fehlt.')); });
        const P = padMap(b), miss = []; DEF.fp1().nets.forEach(n => n.pins.forEach(pin => { if (!P[pin]) miss.push(pin); }));
        out.push(L(miss.length === 0 && b.parts.some(p => p.ref === 'J1'), 'Alle Pins der Netzliste haben ein Pad', 'Zu diesen Pins gibt es kein Pad: ' + miss.join(', ') + '.'));
        out.push(lnDrc(b, ['unconnected']));
        return out;
      } },
    { id: 'pb3', lab: 'pcb', cat: 'Grundlagen', title: 'Pin 1 beim IC: den 555 richtig herum einsetzen', level: 1,
      text: 'Auf der einseitigen Blinker-Platine ist der NE555 (U1) um 180 Grad verdreht eingesetzt: Die Bahnen laufen an die falschen Pins. Bei DIP-Gehäusen liegt Pin 1 links oben, dann geht es links nach unten und rechts wieder nach oben. Setze den IC richtig, sodass die Platine wieder vollständig verbunden und ohne Kurzschluss ist.',
      hint: ['Ein DIP-IC wird links oben mit Pin 1 gezählt, gegen den Uhrzeigersinn. Schau, welche Pads die Bahnen jetzt treffen.', 'Dreh das Bauteil U1 um 180 Grad (Drehen-Werkzeug oder Eigenschaften). Der Rest der Platine bleibt, wie er ist.', 'U1: Drehung auf 0 Grad stellen. Danach meldet der DRC keine Kurzschlüsse und keine offenen Verbindungen mehr.'],
      start: () => { const b = board('ex555'); b.parts.find(p => p.ref === 'U1').rot = 180; return b; }, sol: () => board('ex555'),
      check(b) { return routeLines(b, DEF.ex555()); } },
    { id: 'pb4', lab: 'pcb', cat: 'Grundlagen', title: 'Eurokarte anlegen und Herstellerregeln eintragen', level: 1,
      text: 'Lege eine Platine im Eurokartenformat an: 160 mm x 100 mm, 2 Lagen, Kupfer 1 oz (35 µm). Trage dazu die Regeln deines Prototypen-Herstellers ein: Mindestabstand 0,15 mm, Mindest-Leiterbahnbreite 0,15 mm, Mindestbohrung 0,3 mm und Mindest-Restring 0,15 mm.',
      hint: ['Öffne die Platinen-Eigenschaften. Dort stehen Größe, Lagenzahl, Kupferdicke und die Entwurfsregeln.', 'Eurokarte: 160 x 100 mm (Breite x Höhe oder umgekehrt). Die vier Regeln stehen unter "Entwurfsregeln".', 'Breite 160, Höhe 100, Lagenzahl 2, Kupfer 1 oz. Regeln: Abstand 0,15, Bahnbreite 0,15, Bohrung 0,3, Restring 0,15 (jeweils in mm).'],
      start: () => board('euro'),
      sol: () => { const b = board('euro'); b.w = 160; b.h = 100; b.layers = 2; b.copperOz = 1; Object.assign(b.rules, { clearance: 0.15, minWidth: 0.15, minDrill: 0.3, annular: 0.15 }); return b; },
      check(b) {
        const r = b.rules || {}, sz = (b.w === 160 && b.h === 100) || (b.w === 100 && b.h === 160);
        return [L(sz, 'Größe 160 mm x 100 mm', 'Die Platine ist ' + f2(b.w, 1) + ' x ' + f2(b.h, 1) + ' mm groß. Eine Eurokarte misst 160 x 100 mm.'),
          L(+b.layers === 2, '2 Lagen', 'Die Platine hat ' + b.layers + ' Lage(n), gefordert sind 2.'),
          L(+b.copperOz === 1, 'Kupferdicke 1 oz (35 µm)', 'Eingestellt sind ' + f2(b.copperOz || 0, 1) + ' oz. 1 oz entspricht 35 µm.'),
          L(near(r.clearance, 0.15, 0.001) && near(r.minWidth, 0.15, 0.001), 'Abstand und Leiterbahnbreite 0,15 mm', 'Abstand ist ' + f2(r.clearance) + ' mm, Bahnbreite ' + f2(r.minWidth) + ' mm, beides soll 0,15 mm sein.'),
          L(near(r.minDrill, 0.3, 0.001) && near(r.annular, 0.15, 0.001), 'Bohrung 0,3 mm und Restring 0,15 mm', 'Bohrung ist ' + f2(r.minDrill) + ' mm, Restring ' + f2(r.annular) + ' mm. Gefordert: 0,3 und 0,15 mm.')];
      } },

    /* ---------------- Leiterbahnen */
    { id: 'pb5', lab: 'pcb', cat: 'Leiterbahnen', title: 'Leiterbahnbreite für 1 A nach IPC', level: 1,
      text: 'In dieser LED-Schaltung fließen in den Netzen VCC und GND je 1 A. Alle Leiterbahnen sind nur 0,2 mm schmal und würden sich zu stark erwärmen. Mach die Bahnen von VCC und GND breit genug nach IPC-2221 (10 K Erwärmung, 1 oz, außen). Die Netze müssen weiter verbunden bleiben und der DRC darf nichts melden. Mach die Bahnen aber nicht übertrieben breit (höchstens 1,5 mm).',
      hint: ['Je mehr Strom, desto mehr Kupferquerschnitt brauchst du. Der Netz-Dialog zeigt dir die nötige Breite zum eingetragenen Strom.', 'Für 1 A bei 1 oz außen und 10 K Erwärmung liefert IPC-2221 etwa 0,30 mm. Nimm also etwas mehr, zum Beispiel 0,4 mm, und stell die Breite bei allen Bahnen der beiden Netze ein.', 'Stelle alle Bahnen der Netze VCC und GND auf 0,4 mm (mindestens 0,31 mm). Die Signalbahnen A1 und A2 bleiben schmal.'],
      start: () => setW(setCur(board('h2'), { VCC: 1, GND: 1 }), () => 0.2),
      sol: () => setW(setCur(board('h2'), { VCC: 1, GND: 1 }), t => (t.net === 'VCC' || t.net === 'GND' ? 0.4 : 0.3)),
      check(b) {
        const out = lnsWidth(b, ['VCC', 'GND']), mx = Math.max.apply(null, b.tracks.map(t => +t.w || 0).concat([0]));
        out.push(L(mx <= 1.5, 'Keine Bahn breiter als 1,5 mm', 'Die breiteste Bahn ist ' + f2(mx) + ' mm. Für 1 A reicht deutlich weniger.'));
        out.push(lnConn(b)); out.push(lnShort(b)); out.push(lnDrc(b));
        return out;
      } },
    { id: 'pb6', lab: 'pcb', cat: 'Leiterbahnen', title: 'Lastschalter mit 3 A: breite Bahnen', level: 2,
      text: 'Ein MOSFET schaltet eine Last mit 3 A. In den Netzen VM, SW und GND sind die Bahnen nur 0,4 mm breit, das reicht nicht. Mach die Bahnen dieser drei Netze breit genug nach IPC-2221 (10 K Erwärmung, außen). Du darfst auch 2 oz Kupfer wählen, dann reicht eine schmalere Bahn. Der DRC muss danach sauber sein, auch die Abstände an den Pads des TO-220.',
      hint: ['Bei 3 A wird die Bahn deutlich breiter als bei 1 A. Der Zusammenhang ist nicht linear, der Netz-Dialog rechnet für dich.', 'Für 3 A, 1 oz, außen, 10 K Erwärmung brauchst du etwa 1,37 mm. Mit 2 oz Kupfer sind es etwa 0,68 mm.', 'Setze die Breite der Netze VM, SW und GND auf 1,4 mm (oder Kupfer auf 2 oz und Breite auf 0,8 mm). Das Gate-Netz G bleibt dünn.'],
      start: () => setW(board('m3'), t => (t.net === 'G' ? 0.25 : 0.4)), sol: () => board('m3'),
      check(b) { const out = lnsWidth(b, ['VM', 'SW', 'GND']); out.push(lnConn(b)); out.push(lnShort(b)); out.push(lnDrc(b)); return out; } },
    { id: 'pb7', lab: 'pcb', cat: 'Leiterbahnen', title: 'Säurefallen entschärfen', level: 2,
      text: 'In der LED-Treiber-Platine haben sich spitze Winkel (Säurefallen) in die Leiterbahnen geschlichen. Beim Ätzen bleibt in so einer Ecke Ätzmittel stehen und frisst zu viel Kupfer weg. Beseitige alle Säurefallen: Führe die Bahnen mit 90-Grad- oder 45-Grad-Ecken. Die Netze müssen verbunden bleiben, der DRC darf keine Fehler melden.',
      hint: ['Ein Winkel zwischen zwei Bahnstücken unter 90 Grad ist eine Säurefalle. Der DRC zeigt dir die Stellen als Warnung.', 'Suche die Bahnen mit einer spitzen Zacke und lösche die überflüssigen Punkte. Ein Knick darf höchstens 45 Grad Richtungsänderung haben, also einen Innenwinkel von 135 Grad.', 'Entferne an jeder markierten Stelle die Zacke oder verlege die Bahn mit Auto-Weg neu. Danach darf der DRC keine Säurefalle mehr melden.'],
      start: () => acidStart(), sol: () => board('exled'),
      check(b) {
        const a = drcOf(b).filter(d => d.type === 'acid');
        return [L(a.length === 0, 'Keine Säurefallen mehr', a.length + ' spitze Winkel, zum Beispiel: ' + msgs(a, 1)), lnNets(b, DEF.exled()), lnConn(b), lnShort(b), lnDrc(b)];
      } },
    { id: 'pb8', lab: 'pcb', cat: 'Leiterbahnen', title: 'Spannungsabfall auf der langen Leitung', level: 3,
      text: 'Der Verbraucher J2 zieht 1 A aus dem 5-V-Netz. Die Leitung VCC ist als Schlangenlinie nur 0,4 mm breit und fast 190 mm lang: Dort fällt viel Spannung ab. Sorge dafür, dass der Spannungsabfall auf der Bahn VCC bei 1 A höchstens 40 mV beträgt (also höchstens 40 mOhm Bahnwiderstand, Kupferdicke nach Platineneinstellung). Du darfst die Bahn verbreitern, kürzer verlegen oder 2 oz Kupfer wählen.',
      hint: ['Der Widerstand einer Bahn ist R = ρ · l / (b · d). Kürzer, breiter oder dicker macht ihn kleiner. ρ von Kupfer ist 1,72 · 10^-8 Ohm · m.', 'Mit 190 mm Länge und 0,4 mm Breite sind es rund 230 mOhm, also 230 mV bei 1 A. Der kürzeste Weg zwischen J1 und J2 ist etwa 65 mm lang.', 'Verlege VCC direkt (gerade) und 1 mm breit: etwa 32 mOhm. Oder lass die Schlangenlinie und mach sie 2,6 mm breit.'],
      start: () => board('h9'), sol: () => setW(board('h9'), t => (t.net === 'VCC' ? 2.6 : null)),
      check(b) {
        const oz = b.copperOz || 1, ts = b.tracks.filter(t => t.net === 'VCC');
        const R = ts.reduce((s, t) => s + CORE().traceResistance(tlen(t), +t.w || 0.001, oz), 0), mv = R * 1000;
        return [L(ts.length > 0 && R <= 0.04 + 1e-9, 'Spannungsabfall bei 1 A höchstens 40 mV', 'Die Bahn VCC hat ' + f2(mv, 0) + ' mOhm, das sind ' + f2(mv, 0) + ' mV bei 1 A. Gefordert sind höchstens 40 mV.'),
          lnConn(b), lnShort(b), lnDrc(b), lnNets(b, DEF.h9())];
      } },

    /* ---------------- Mehrlagen */
    { id: 'pb9', lab: 'pcb', cat: 'Mehrlagen', title: 'Via setzen: Lagenwechsel', level: 1,
      text: 'Der Widerstand R1 sitzt oben, R2 unten auf der Platine. Die Leiterbahn von R1 endet oben bei x = 20 mm, die Fortsetzung beginnt unten an derselben Stelle: Dazwischen fehlt die Durchkontaktierung. Setze ein Via im Netz N1, sodass alles verbunden ist. Der DRC darf keinen Fehler melden.',
      hint: ['Um die Lage zu wechseln, braucht die Leiterbahn ein Via: ein verkupfertes Loch, das Oberseite und Unterseite verbindet.', 'Die obere Bahn endet bei (20 | 8) mm, die untere beginnt dort. Setze das Via genau auf diesen Punkt und gib ihm das Netz N1.', 'Via-Werkzeug wählen, auf (20 | 8) tippen, Netz N1 zuweisen. Standardgröße 0,8 mm Durchmesser und 0,4 mm Bohrung ist richtig.'],
      start: () => { const b = board('h3'); b.vias = b.vias.filter(v => v.net !== 'N1'); return b; }, sol: () => board('h3'),
      check(b) {
        const n = b.vias.filter(v => v.net === 'N1').length;
        return routeLines(b, DEF.h3()).concat([L(n >= 1 && n <= 2, 'Ein Via im Netz N1 (nicht mehr als zwei)', 'Im Netz N1 sind ' + n + ' Vias, du brauchst genau einen Lagenwechsel.')]);
      } },
    { id: 'pb10', lab: 'pcb', cat: 'Mehrlagen', title: 'Massefläche auf der Unterseite anlegen', level: 2,
      text: 'Beim OPV-Vorverstärker sind alle Signale oben verlegt, aber die Masse (GND) ist noch gar nicht verbunden. Lege auf der Unterseite eine Kupferfläche im Netz GND an, die mindestens 70 Prozent der Platine bedeckt, und verbinde die SMD-Pads mit Vias an die Fläche. Die Pins der Stiftleisten treffen die Fläche selbst. Setze dabei nicht mehr als 12 Vias.',
      hint: ['Eine Massefläche ist die kürzeste Masseverbindung: Jedes GND-Pad bekommt ein Via nach unten, der Rest erledigt das Kupfer.', 'Zeichne mit dem Flächen-Werkzeug ein Rechteck über die Platine auf B.Cu und weise das Netz GND zu. SMD-Pads brauchen je ein Via. Der Auto-Weg setzt sie für dich.', 'Fläche auf B.Cu, Netz GND, Rechteck fast über die ganze Platine. Dann Auto-Weg für das Netz GND: Es entstehen etwa fünf Vias.'],
      start: () => { const b = board('exopv'); b.zones = []; b.vias = []; return b; }, sol: () => board('exopv'),
      check(b) {
        const c = cover(b, 'GND', l => l === 'B.Cu' || l === 'F.Cu'), n = zones(b, 'GND', l => l === 'B.Cu' || l === 'F.Cu').length;
        return [L(n > 0, 'Es gibt eine GND-Fläche auf einer Außenlage', 'Zeichne eine Kupferfläche auf B.Cu und weise ihr das Netz GND zu.'),
          L(c >= 0.7, 'Die Fläche bedeckt mindestens 70 % der Platine', 'Die GND-Fläche deckt nur ' + f2(c * 100, 0) + ' % der Platine ab.'),
          lnConn(b), lnShort(b), lnDrc(b), lnVias(b, 12), lnNets(b, DEF.exopv())];
      } },
    { id: 'pb11', lab: 'pcb', cat: 'Mehrlagen', title: 'GND-Fläche auf der Innenlage In1 (4 Lagen)', level: 2,
      text: 'Die 4-Lagen-Platine hat schon eine Versorgungsebene (VCC auf In2.Cu). Es fehlt die Masse: Lege auf einer Innenlage eine Kupferfläche im Netz GND an, die mindestens 70 Prozent der Platine bedeckt (üblich ist In1, direkt unter den Signalen), und verbinde alle GND-Pads mit Vias. Die VCC-Ebene darf nicht gestört werden. Nicht mehr als 14 Vias.',
      hint: ['Bei vier Lagen liegt die Masse direkt unter den Signalen: Das gibt kurze Rückstrompfade und schirmt ab.', 'Flächen-Werkzeug auf In1.Cu, Netz GND, Rechteck über die Platine. Danach bekommt jedes GND-Pad ein Via, das durch alle Lagen geht. Der Auto-Weg erledigt das für das Netz GND.', 'Zone GND auf In1.Cu über die ganze Platine, dann Auto-Weg nur für GND. Die VCC-Zone auf In2.Cu bleibt unverändert.'],
      start: () => board('m4vcc'), sol: () => board('m4s11'),
      check(b) {
        const inn = l => isInner(l), c = cover(b, 'GND', inn), v = zones(b, 'VCC', l => l === 'In2.Cu').length;
        return [L(zones(b, 'GND', inn).length > 0, 'Es gibt eine GND-Fläche auf einer Innenlage', 'Zeichne die Fläche auf In1.Cu und weise ihr das Netz GND zu.'),
          L(c >= 0.7, 'Die GND-Fläche bedeckt mindestens 70 % der Platine', 'Die Fläche deckt nur ' + f2(c * 100, 0) + ' % der Platine ab.'),
          L(v > 0, 'Die VCC-Ebene auf In2.Cu ist unverändert', 'Die Versorgungsebene auf In2.Cu wurde gelöscht oder verschoben.'),
          lnConn(b), lnShort(b), lnDrc(b), lnVias(b, 14)];
      } },
    { id: 'pb12', lab: 'pcb', cat: 'Mehrlagen', title: 'Versorgungsebene VCC anlegen', level: 2,
      text: 'Die Logikplatine hat eine GND-Fläche auf In1.Cu, aber die 3,3-V-Versorgung (Netz VCC) ist noch nicht verlegt. Lege auf einer Innenlage eine VCC-Ebene an, die mindestens 40 Prozent der Platine bedeckt (üblich ist In2), und verbinde alle VCC-Pads mit Vias. Die Massefläche darf sich mit der Versorgungsebene nicht überlappen. Nicht mehr als 14 Vias.',
      hint: ['Auch die Versorgung kann als Ebene geführt werden: Das senkt die Impedanz der Stromversorgung und spart Leiterbahnen.', 'Eine Fläche pro Innenlage und Netz: In1 gehört schon der Masse, also nimm In2 für VCC. Danach braucht jedes VCC-Pad ein Via.', 'Zone VCC auf In2.Cu über die Platine, danach Auto-Weg für das Netz VCC. Alle Pads (U1.14, C1, C2, J1.1, U2 Pin 2 und 4) werden angebunden.'],
      start: () => board('m4gnd'), sol: () => board('m4s12'),
      check(b) {
        const inn = l => isInner(l), c = cover(b, 'VCC', inn), g = zones(b, 'GND', l => l === 'In1.Cu').length;
        return [L(zones(b, 'VCC', inn).length > 0, 'Es gibt eine VCC-Fläche auf einer Innenlage', 'Zeichne die Fläche auf In2.Cu und weise ihr das Netz VCC zu.'),
          L(c >= 0.4, 'Die VCC-Ebene bedeckt mindestens 40 % der Platine', 'Die Fläche deckt nur ' + f2(c * 100, 0) + ' % der Platine ab.'),
          L(g > 0, 'Die GND-Fläche auf In1.Cu ist unverändert', 'Die Massefläche auf In1.Cu wurde gelöscht oder verschoben.'),
          lnConn(b), lnShort(b), lnDrc(b), lnVias(b, 14)];
      } },
    { id: 'pb13', lab: 'pcb', cat: 'Mehrlagen', title: 'Lagenaufbau wählen: von 4 auf 6 Lagen', level: 2,
      text: 'Die Logikplatine ist so eng geworden, dass du zwei zusätzliche Signallagen brauchst. Stelle sie auf 6 Lagen um und wähle den Lagenaufbau: Signal oben, In1 Masse (GND), In2 und In3 Signal, In4 Versorgung (VCC), Signal unten. Die Platine muss danach vollständig verbunden und DRC-sauber bleiben.',
      hint: ['Beim 6-Lagen-Standard liegen Masse und Versorgung als Ebenen jeweils neben einer Signallage, in der Mitte bleibt Platz für zwei Signallagen.', 'Ändere die Lagenzahl in den Platinen- oder Lagen-Einstellungen auf 6. Die Versorgungsebene muss von In2 auf In4 ziehen, die Masse bleibt auf In1.', 'Lagenzahl 6; Zone GND auf In1.Cu, Zone VCC auf In4.Cu; In2.Cu und In3.Cu bleiben frei für Signale.'],
      start: () => board('m4full'),
      sol: () => { const b = board('m4full'); b.layers = 6; b.zones.forEach(z => { if (z.net === 'VCC') z.layer = 'In4.Cu'; }); b.layerRoles = { 'In1.Cu': 'gnd', 'In2.Cu': 'signal', 'In3.Cu': 'signal', 'In4.Cu': 'vcc' }; return b; },
      check(b) {
        const rs = id => roleOf(b, id);
        return [L(+b.layers === 6, 'Die Platine hat 6 Lagen', 'Die Platine hat ' + b.layers + ' Lagen, gefordert sind 6.'),
          L(rs('In1.Cu') === 'gnd', 'In1 ist die Masselage', 'In1.Cu ist als "' + rs('In1.Cu') + '" belegt, dort gehört die Masse (GND) hin.'),
          L(rs('In4.Cu') === 'vcc', 'In4 ist die Versorgungslage', 'In4.Cu ist als "' + rs('In4.Cu') + '" belegt, dort gehört die Versorgung (VCC) hin.'),
          L(rs('In2.Cu') === 'signal' && rs('In3.Cu') === 'signal', 'In2 und In3 sind Signallagen', 'In2 ist "' + rs('In2.Cu') + '", In3 ist "' + rs('In3.Cu') + '". Beide sollen frei für Signale bleiben.'),
          lnConn(b), lnShort(b), lnDrc(b)];
      } },
    { id: 'pb14', lab: 'pcb', cat: 'Mehrlagen', title: 'Rückstrompfad: Takt über die Massefläche', level: 3,
      text: 'Die Taktleitung CLK läuft auf der Unterseite quer durch die GND-Fläche und zerschneidet sie in zwei Hälften. Der Rückstrom des Takts muss dann einen Umweg nehmen und die Schleife strahlt ab. Verlege die Taktleitung so, dass die Massefläche nicht mehr zerschnitten wird (der DRC meldet keinen Flächenschnitt), und lass alle Netze verbunden.',
      hint: ['Der Strom fließt immer im Kreis: Das Signal hin, der Rückstrom unter dem Signal zurück. Eine Lücke in der Fläche zwingt ihn zum Umweg.', 'Die Massefläche liegt auf B.Cu. Wenn die Taktbahn auf der anderen Lage (F.Cu) läuft, kreuzt sie die Fläche nicht mehr. Die Pads der Stiftleisten sind auf beiden Lagen erreichbar.', 'Lege die Bahn CLK auf F.Cu (Lage der Bahn ändern oder neu zeichnen). Die GND-Fläche und die zwei GND-Bahnen bleiben unverändert.'],
      start: () => board('h6'), sol: () => { const b = board('h6'); b.tracks.forEach(t => { if (t.net === 'CLK') t.layer = 'F.Cu'; }); return b; },
      check(b) {
        const s = drcOf(b).filter(d => d.type === 'planesplit');
        return [L(s.length === 0, 'Die Massefläche wird nicht zerschnitten', s.length + ' Bahn(en) zerschneiden die Fläche: ' + msgs(s, 1)), lnConn(b), lnShort(b), lnDrc(b), lnNets(b, DEF.h6()),
          L(zones(b, 'GND').length > 0, 'Die GND-Fläche ist noch vorhanden', 'Du hast die Massefläche gelöscht. Sie soll bleiben und nur nicht zerschnitten werden.')];
      } },
    { id: 'pb15', lab: 'pcb', cat: 'Mehrlagen', title: 'Impedanz: 50-Ohm-Leitung zur Antenne', level: 3,
      text: 'Die Antennenleitung ANT läuft auf F.Cu über der Massefläche auf In1 (Prepreg 0,2 mm, εr etwa 4,2, 1 oz Kupfer). Mit 0,15 mm Breite ist sie viel zu hochohmig. Mach die Leitung so breit, dass sie als Mikrostreifenleitung eine Impedanz von 50 Ohm hat (Toleranz plus/minus 10 %, also 45 bis 55 Ohm). Die Leitung muss auf der Außenlage bleiben, und der DRC darf nichts melden.',
      hint: ['Breite Leitung = geringere Impedanz. Die Impedanz hängt von Breite, Höhe über der Massefläche und der Dielektrizitätszahl ab.', 'Im Lagen-Tab steht der Impedanzrechner (Mikrostreifen). Mit h = 0,2 mm, εr = 4,2 und t = 35 µm ergibt eine Breite von etwa 0,35 mm ungefähr 50 Ohm.', 'Stelle die Breite aller Bahnen im Netz ANT auf 0,35 mm. Zwischen 0,31 und 0,39 mm liegst du im Toleranzband.'],
      start: () => board('h7'), sol: () => setW(board('h7'), t => (t.net === 'ANT' ? 0.35 : null)),
      check(b) {
        const ts = b.tracks.filter(t => t.net === 'ANT'), outer = ts.every(t => t.layer === 'F.Cu' || t.layer === 'B.Cu');
        const zs = ts.map(t => { const ref = t.layer === 'B.Cu' ? 'In2.Cu' : 'In1.Cu', d = CORE().dielectricBetween(b, t.layer, ref); return { t, z: CORE().microstrip(+t.w, d.h, d.er, 0.035 * (b.copperOz || 1)) }; });
        const bad = zs.filter(x => !(x.z >= 45 && x.z <= 55));
        return [L(ts.length > 0 && bad.length === 0, 'Die Leitung ANT hat 50 Ohm (45 bis 55 Ohm)', () => ts.length === 0 ? 'Das Netz ANT hat keine Leiterbahn.' : !(bad[0].z > 0) ? 'Bahn ' + bad[0].t.id + ' ist mit ' + f2(bad[0].t.w) + ' mm viel zu breit für die Höhe über der Massefläche: Die Mikrostreifen-Formel gilt dort nicht mehr, die Impedanz läge weit unter 50 Ohm. Mach die Bahn deutlich schmaler (um 0,35 mm).' : 'Bahn ' + bad[0].t.id + ' (' + f2(bad[0].t.w) + ' mm breit) hat etwa ' + f2(bad[0].z, 0) + ' Ohm. Verbreitere sie für weniger Ohm, verschmälere sie für mehr.'),
          L(ts.length > 0 && outer, 'ANT bleibt auf einer Außenlage (Mikrostreifen)', 'Die Formel gilt für Außenlagen. Lege die Leitung auf F.Cu oder B.Cu.'),
          lnConn(b), lnShort(b), lnDrc(b), L(zones(b, 'GND', l => l === 'In1.Cu').length > 0, 'Die Massefläche auf In1 ist noch da', 'Ohne Bezugsfläche gibt es keine definierte Impedanz.')];
      } },

    /* ---------------- Layout */
    { id: 'pb16', lab: 'pcb', cat: 'Layout', title: 'Netzliste verlegen: 555-Blinker auf 2 Lagen', level: 2,
      text: 'Verlege die Netzliste des 555-Blinkers auf der 2-Lagen-Platine: alle fünf Netze (VCC, GND, N1, N2, OUT) müssen verbunden sein, ohne Kurzschluss und ohne DRC-Fehler. Setze nicht mehr als 6 Vias. Mit dem Auto-Weg geht es schnell, du kannst aber auch von Hand verlegen.',
      hint: ['Beginne mit den wichtigen Netzen: Versorgung und Masse zuerst, dann die Signale. Bahnen auf der Oberseite und der Unterseite dürfen sich kreuzen.', 'Zwei Bahnen auf derselben Lage dürfen sich nicht kreuzen. Wenn es nicht anders geht, wechsle mit einem Via die Lage. Der Auto-Weg erledigt das automatisch.', 'Markiere alle Netze und starte den Auto-Weg. Prüfe danach den DRC. Wenn Netze offen bleiben, schiebe ein Bauteil etwas zur Seite und starte neu.'],
      start: () => DEF.u555_2(), sol: () => board('u555_2'),
      check(b) { return routeLines(b, DEF.u555_2(), { vias: 6 }); } },
    { id: 'pb17', lab: 'pcb', cat: 'Layout', title: 'Einseitige Platine: alles auf der Lötseite', level: 3,
      text: 'Verlege den 555-Blinker auf einer einseitigen Platine: Alle Leiterbahnen liegen auf der Lötseite (B.Cu), es gibt kein Via, und die Platine bleibt einseitig (1 Lage). Alle fünf Netze müssen verbunden und der DRC sauber sein. Die Bauteile stehen oben, THT-Pads sind von unten erreichbar.',
      hint: ['Bei einer einseitigen Platine gibt es nur eine Kupferlage. Zwei Bahnen dürfen sich dort nie kreuzen.', 'Plane die Reihenfolge so, dass keine Bahn eine andere kreuzen muss. Ein Auto-Weg auf einer Lage findet oft eine Lösung, sonst hilft Umplatzieren.', 'Starte den Auto-Weg, lass nur B.Cu zu und prüfe, ob alles verbunden ist. Es dürfen weder Vias noch Bahnen auf F.Cu entstehen.'],
      start: () => DEF.ex555(), sol: () => board('ex555'),
      check(b) {
        const top = b.tracks.filter(t => t.layer !== 'B.Cu').length;
        return routeLines(b, DEF.ex555()).concat([L(+b.layers === 1, 'Die Platine bleibt einseitig (1 Lage)', 'Die Platine hat ' + b.layers + ' Lagen.'), L(top === 0 && b.vias.length === 0, 'Alle Bahnen auf B.Cu, keine Vias', top + ' Bahn(en) liegen nicht auf B.Cu, ' + b.vias.length + ' Via(s) gesetzt.')]);
      } },
    { id: 'pb18', lab: 'pcb', cat: 'Layout', title: 'Sensorknoten auf 4 Lagen verlegen', level: 3,
      text: 'Die 4-Lagen-Platine des Sensorknotens hat schon GND auf In1 und VCC auf In2 als Flächen. Verlege alle Netze: Signale auf den Außenlagen, Masse und Versorgung über Vias an die Flächen. Die Flächen auf In1 und In2 dürfen dabei nicht durch Bahnen zerschnitten werden. Es müssen alle Netze verbunden sein, ohne DRC-Fehler und mit höchstens 40 Vias.',
      hint: ['Masse und Versorgung brauchst du nicht zu verlegen: Jedes Pad bekommt nur ein kurzes Via zur passenden Fläche.', 'Alle Signalbahnen (SDA, SCL, MOSI ...) verlegst du auf F.Cu und B.Cu. Die Innenlagen In1 und In2 bleiben reine Ebenen ohne Bahnen.', 'Auto-Weg für alle Netze: Er setzt die Vias zu den Flächen selbst und verlegt die Signale außen. Prüfe danach den DRC.'],
      start: () => DEF.exsensor(), sol: () => board('exsensor'),
      check(b) {
        const inTr = b.tracks.filter(t => t.layer === 'In1.Cu' || t.layer === 'In2.Cu').length;
        return routeLines(b, DEF.exsensor(), { vias: 40 }).concat([L(zones(b, 'GND', l => l === 'In1.Cu').length > 0 && zones(b, 'VCC', l => l === 'In2.Cu').length > 0, 'GND-Fläche auf In1 und VCC-Fläche auf In2 sind erhalten', 'Eine der beiden Flächen fehlt.'), L(inTr === 0, 'Auf den Ebenen In1 und In2 liegen keine Bahnen', inTr + ' Bahn(en) liegen auf In1/In2 und zerschneiden die Fläche.')]);
      } },
    { id: 'pb19', lab: 'pcb', cat: 'Layout', title: 'Abblockkondensator nah an den IC', level: 2,
      text: 'Der Abblockkondensator C1 (100 nF) soll Spannungsspitzen direkt am Versorgungspin des OPV U1 (Pin 8, VCC) abfangen. Er liegt aber weit weg in der Ecke. Platziere C1 so, dass sein VCC-Pad höchstens 6 mm vom Pin 8 des ICs entfernt ist, und verlege danach die ganze Platine: alle Netze verbunden, DRC ohne Fehler.',
      hint: ['Der Kondensator liefert den Strom für schnelle Schaltvorgänge. Je länger die Leitung zum IC, desto mehr Induktivität steht dazwischen.', 'Pin 8 (VCC) sitzt oben rechts am SOIC-8. Platziere C1 direkt daneben und prüfe den Abstand mit dem Messwerkzeug.', 'C1 etwa nach (32 | 8) setzen (rechts oberhalb von U1). Dann Auto-Weg starten und den DRC prüfen.'],
      start: () => board('abl'), sol: () => board('abl_ok'),
      check(b) {
        const P = padMap(b), c = P['C1.1'], u = P['U1.8'], d = c && u ? Math.hypot(c.x - u.x, c.y - u.y) : 99;
        const ref = DEF.abl(), pm = b.parts.map(p => p.ref + ':' + p.fp).sort().join(',') === ref.parts.map(p => p.ref + ':' + p.fp).sort().join(',');
        return [L(pm, 'Alle Bauteile sind noch vorhanden', 'Es fehlen Bauteile oder ein Footprint wurde geändert.'), lnNets(b, ref),
          L(d <= 6, 'C1 liegt höchstens 6 mm vom VCC-Pin des ICs', 'Das VCC-Pad von C1 ist ' + f2(d, 1) + ' mm von U1 Pin 8 entfernt. Gefordert sind höchstens 6 mm.'), lnConn(b), lnShort(b), lnDrc(b)];
      } },
    { id: 'pb20', lab: 'pcb', cat: 'Layout', title: 'Quarz kurz anbinden', level: 3,
      text: 'Der Quarz Y1 mit seinen beiden Lastkondensatoren C1 und C2 liegt weit weg vom Mikrocontroller U1 (Pins 6 und 7). Lange Taktleitungen strahlen ab und verstimmen den Schwinger. Platziere Y1, C1 und C2 dicht an U1 und verlege alle Netze. Die beiden Quarz-Netze XT1 und XT2 dürfen je höchstens 16 mm Bahnlänge haben und kein Via enthalten. Der DRC muss sauber sein.',
      hint: ['Beim Quarz zählt die Länge der Leitung zum Controller: kurz, ohne Lagenwechsel, und die Lastkondensatoren dicht dabei.', 'Pin 6 und 7 liegen an der linken Seite von U1. Setze Y1 gleich links davon und die beiden Kondensatoren darunter.', 'Y1 etwa nach (21 | 20), C1 nach (16 | 22) und C2 nach (19 | 24) setzen, die Kondensatoren um 90 Grad gedreht. Dann Auto-Weg für alle Netze.'],
      start: () => board('qz'), sol: () => board('qz_ok'),
      check(b) {
        const ref = DEF.qz(), l1 = netLen(b, 'XT1'), l2 = netLen(b, 'XT2'), v = b.vias.filter(x => x.net === 'XT1' || x.net === 'XT2').length;
        return [lnParts(b, ref), lnNets(b, ref), lnConn(b), lnShort(b), lnDrc(b),
          L(l1 > 0 && l1 <= 16, 'Netz XT1 ist höchstens 16 mm lang', 'XT1 hat ' + f2(l1, 1) + ' mm Bahnlänge' + (l1 === 0 ? ' (noch nicht verlegt)' : '') + '. Rücke Y1 und C1 näher an U1.'),
          L(l2 > 0 && l2 <= 16, 'Netz XT2 ist höchstens 16 mm lang', 'XT2 hat ' + f2(l2, 1) + ' mm Bahnlänge' + (l2 === 0 ? ' (noch nicht verlegt)' : '') + '. Rücke Y1 und C2 näher an U1.'),
          L(v === 0, 'Die Quarz-Netze haben kein Via', 'Die Taktleitung wechselt die Lage. Das stört die Rückstromführung, verlege sie auf einer Lage.')];
      } },

    /* ---------------- DRC beheben */
    { id: 'pb21', lab: 'pcb', cat: 'DRC beheben', title: 'DRC: Abstand zu klein', level: 1,
      text: 'Der DRC meldet auf dieser Platine einen Abstandsfehler: Zwei Leiterbahnen verschiedener Netze liegen zu dicht beieinander. Behebe den Fehler, ohne die Verbindungen zu verändern und ohne die Entwurfsregeln aufzuweichen.',
      hint: ['Der Mindestabstand schützt vor Kurzschluss beim Ätzen und Löten. Der DRC markiert die Stelle mit einem roten Kreis.', 'Die Bahn A2 macht einen Umweg direkt unter der Bahn A1. Verschiebe die waagerechte Strecke weiter nach unten oder führe A2 geradeaus.', 'Lösche den Umweg und verlege A2 gerade von R2 zu D2, oder schiebe das Teilstück etwa 2 mm nach unten. Der Abstand muss mindestens 0,2 mm sein.'],
      start: () => board('h2_abst'), sol: () => board('h2'),
      check(b) {
        const c = errsOf(b).filter(d => d.type === 'clearance');
        return [L(c.length === 0, 'Kein Abstandsfehler mehr', c.length + ' Abstandsfehler, zum Beispiel: ' + msgs(c, 1)), lnConn(b), lnShort(b), lnDrc(b), lnRules(b), lnNets(b, DEF.h2())];
      } },
    { id: 'pb22', lab: 'pcb', cat: 'DRC beheben', title: 'DRC: Kurzschluss und offene Verbindung', level: 2,
      text: 'Auf dieser Platine gibt es zwei Fehler: Eine Bahn kreuzt eine fremde Bahn (Kurzschluss), und eine Verbindung im Netz VCC fehlt ganz (Luftlinie offen). Behebe beide Fehler, ohne die Entwurfsregeln aufzuweichen. Danach muss der DRC sauber sein.',
      hint: ['Ein Kurzschluss entsteht, wo Kupfer verschiedener Netze sich berührt. Eine offene Verbindung zeigt der DRC als Luftlinie.', 'Die Bahn A2 läuft zweimal quer über A1. Verlege sie so, dass sie A1 nicht schneidet. In VCC fehlt die Verbindung zu R2, Pin 1.', 'A2 gerade von R2.2 nach D2.2 führen, dann VCC von dem Eckpunkt bei x = 10 mm nach unten (y = 20) und bis R2.1 ziehen.'],
      start: () => board('h2_kurz'), sol: () => board('h2'),
      check(b) { return [lnShort(b), lnConn(b), lnDrc(b), lnRules(b), lnNets(b, DEF.h2())]; } },
    { id: 'pb23', lab: 'pcb', cat: 'DRC beheben', title: 'DRC: Strom, Breite und Randabstand', level: 3,
      text: 'Hier stecken drei Fehlerarten: In den Netzen VCC und GND (je 2 A) sind die Bahnen zu schmal, die Signalbahn A1 unterschreitet die Mindestbreite, und die GND-Bahn läuft am rechten Platinenrand entlang. Behebe alles, sodass der DRC sauber ist. Die Ströme in der Netzliste und die Regeln dürfen nicht verändert werden.',
      hint: ['Es gibt drei Meldungstypen: Strombelastbarkeit (current), Mindestbreite (width) und Randabstand (edge). Lies die Meldungen im DRC-Fenster.', 'Für 2 A bei 1 oz außen brauchst du etwa 0,78 mm. A1 muss mindestens 0,2 mm breit sein. Die GND-Bahn muss mindestens 0,3 mm vom Rand weg.', 'VCC und GND auf 0,8 mm verbreitern, A1 auf 0,3 mm, und die senkrechte GND-Strecke von x = 43,8 mm nach etwa x = 39 mm verschieben.'],
      start: () => setCur(board('h2_schmal'), { VCC: 2, GND: 2 }), sol: () => setCur(board('h2_schmal_sol'), { VCC: 2, GND: 2 }),
      check(b) {
        const e = errsOf(b), has = t => e.filter(d => d.type === t);
        const cur = ['VCC', 'GND'].every(n => { const x = b.nets.find(q => q.name === n); return x && x.current >= 2; });
        return [L(has('current').length === 0, 'Alle Bahnen vertragen den Strom', has('current').length + ' Strom-Meldung(en): ' + msgs(has('current'), 1)),
          L(has('width').length === 0, 'Keine Bahn unterschreitet die Mindestbreite', msgs(has('width'), 1)), L(has('edge').length === 0, 'Alle Bahnen haben genug Randabstand', msgs(has('edge'), 1)),
          lnConn(b), lnDrc(b), lnRules(b), L(cur, 'Die Ströme der Netze (2 A) sind unverändert eingetragen', 'Der Strom in der Netzliste darf nicht gelöscht oder verkleinert werden.')];
      } },

    /* ---------------- Fertigung */
    { id: 'pb24', lab: 'pcb', cat: 'Fertigung', title: 'Herstellerregeln einhalten (Prototyp)', level: 2,
      text: 'Dein Prototypen-Hersteller verlangt: Leiterbahnbreite mindestens 0,15 mm, Abstand mindestens 0,15 mm, Bohrung mindestens 0,3 mm, Restring mindestens 0,15 mm. Trage diese Werte in die Entwurfsregeln der Platine ein (sie sind jetzt zu locker eingestellt) und behebe dann alle Verstöße, die der DRC damit findet. Die Verbindungen bleiben erhalten.',
      hint: ['Der DRC prüft nur gegen die Regeln, die du eingestellt hast. Stehen sie zu locker, bleiben Fertigungsprobleme unsichtbar.', 'Stelle zuerst die Regeln auf die Herstellerwerte. Danach melden sich eine zu schmale Bahn und ein zu kleiner Abstand.', 'Regeln: Abstand 0,15, Bahnbreite 0,15, Bohrung 0,3, Restring 0,15. Dann die Bahn A2 breiter als 0,15 mm machen und ihren Umweg weiter von A1 wegschieben (Lücke mindestens 0,15 mm).'],
      start: () => mfgStart(),
      sol: () => { const b = board('h2'); Object.assign(b.rules, { clearance: 0.15, minWidth: 0.15, minDrill: 0.3, annular: 0.15 }); return b; },
      check(b) {
        const r = b.rules || {}, rules = { minWidth: Math.max(0.15, r.minWidth || 0), clearance: Math.max(0.15, r.clearance || 0), minDrill: Math.max(0.3, r.minDrill || 0), annular: Math.max(0.15, r.annular || 0) };
        const e = errsOf(b, ['unconnected'], { rules }), has = t => e.filter(d => d.type === t);
        const set = !(r.minWidth < 0.15 - 1e-9) && !(r.clearance < 0.15 - 1e-9) && !(r.minDrill < 0.3 - 1e-9) && !(r.annular < 0.15 - 1e-9);
        return [L(set, 'Die Entwurfsregeln entsprechen den Herstellerwerten', 'Eingestellt: Bahn ' + f2(r.minWidth) + ', Abstand ' + f2(r.clearance) + ', Bohrung ' + f2(r.minDrill) + ', Restring ' + f2(r.annular) + ' mm. Gefordert: mindestens 0,15 / 0,15 / 0,3 / 0,15 mm.'),
          L(has('width').length === 0, 'Keine Bahn ist schmaler als 0,15 mm', msgs(has('width'), 1)), L(has('clearance').length === 0, 'Alle Abstände sind mindestens 0,15 mm', msgs(has('clearance'), 1)),
          L(e.length === 0, 'Der DRC mit den Herstellerregeln meldet keine Fehler', msgs(e, 2)), lnConn(b), lnNets(b, DEF.h2())];
      } },
    { id: 'pb25', lab: 'pcb', cat: 'Fertigung', title: 'Bohrung und Restring der Vias', level: 2,
      text: 'Der Hersteller verlangt eine Mindestbohrung von 0,3 mm und einen Restring von mindestens 0,15 mm. Zwei Vias der Platine verletzen das: Eines hat nur 0,05 mm Restring, das andere ist mit 0,2 mm Bohrung zu fein (und damit teurer). Ändere die Via-Maße so, dass beide Regeln eingehalten werden. Der Restring ist (Durchmesser minus Bohrung) geteilt durch 2.',
      hint: ['Das Via besteht aus einer Bohrung und einem Kupferring darum. Der Ring heißt Restring: (Durchmesser - Bohrung) / 2.', 'Bei 0,5 mm Durchmesser und 0,4 mm Bohrung bleibt nur 0,05 mm Ring. Mach den Durchmesser größer oder die Bohrung kleiner (aber nicht unter 0,3 mm).', 'Nimm 0,8 mm Durchmesser und 0,4 mm Bohrung für beide Vias: Restring 0,2 mm.'],
      start: () => viasBad(board('h3')), sol: () => board('h3'),
      check(b) {
        const v = b.vias, dr = v.filter(x => (+x.drill || 0) < 0.3 - 1e-9), an = v.filter(x => ((+x.dia || 0) - (+x.drill || 0)) / 2 < 0.15 - 1e-9);
        return [L(v.length > 0 && dr.length === 0, 'Alle Bohrungen sind mindestens 0,3 mm', dr.length + ' Via(s) haben weniger als 0,3 mm Bohrung (zum Beispiel ' + (dr[0] ? f2(dr[0].drill) + ' mm' : '') + ').'),
          L(v.length > 0 && an.length === 0, 'Alle Restringe sind mindestens 0,15 mm', an.length + ' Via(s) haben zu wenig Restring: ' + (an[0] ? f2(((+an[0].dia) - (+an[0].drill)) / 2) + ' mm' : '') + '.'),
          lnDrc(b), lnConn(b), lnRules(b), lnVias(b, 4)];
      } },
    { id: 'pb26', lab: 'pcb', cat: 'Fertigung', title: 'Gerber-Dateien richtig zuordnen', level: 1,
      text: 'Dein Layout liegt als Gerber-Paket vor (Dateien blinker-F_Cu.gtl, blinker-B_Cu.gbl, ...). Ordne jeder Dateiendung die Lage oder den Zweck zu. Die Endungen folgen der Gerber-Konvention (G = Gerber, T = Top, B = Bottom, L = Layer).',
      hint: ['Das dritte Zeichen der Endung verrät die Lage: T = oben (Top), B = unten (Bottom). Der Buchstabe danach sagt, was es ist.', '.gtl und .gbl sind Kupfer, .gts und .gbs Lötstopplack (Solder mask), .gtp Lotpaste (Paste), .gto und .gbo Bestückungsdruck (Overlay/Silk).', '.gtl Kupfer oben, .gbl Kupfer unten, .gts/.gbs Lötstopplack oben/unten, .gtp Lotpaste oben, .gto/.gbo Bestückungsdruck oben/unten, .gm1 Platinenumriss, .drl Bohrungen.'],
      start: () => withAnswers(board('u555_2'), {}), sol: () => withAnswers(board('u555_2'), gerberSol()), answer: gerberAns(),
      check(b) {
        const a = A(b), files = Object.keys((CORE().gerber(b, { name: 'blinker' }) || {}).files || {});
        return GERBER.map(g => { const has = files.some(f => f.slice(-g[0].length) === g[0]); return L(has && a[g[0]] === g[1], 'Endung ' + g[0] + ' gehört zu: ' + g[1], a[g[0]] ? '"' + a[g[0]] + '" ist nicht richtig für ' + g[0] + '.' : 'Für ' + g[0] + ' fehlt noch deine Zuordnung.'); });
      } },
    { id: 'pb27', lab: 'pcb', cat: 'Fertigung', title: 'Platinenkosten senken: Fläche passend wählen', level: 2,
      text: 'Die Platine ist 100 mm x 80 mm groß, obwohl der LED-Treiber nur etwa die Hälfte braucht. Die Fläche bestimmt den Preis. Verkleinere den Platinenumriss so weit, dass die Platine für 10 Stück höchstens 10 Prozent teurer ist als die Musterlösung (46 mm x 34 mm). Bauteile und Bahnen müssen dabei im Umriss bleiben (Randabstand mindestens 0,3 mm), alle Netze verbunden.',
      hint: ['Der Preis hängt von der Fläche, der Lagenzahl, der Zahl der Bohrungen und der Oberfläche ab. Hier bleibt nur die Fläche zum Sparen.', 'Miss, wo das letzte Bauteil oder die letzte Bahn endet, und gib 2 bis 3 mm Rand dazu. Breite und Höhe stellst du in den Platinen-Eigenschaften ein.', 'Breite 46 mm, Höhe 34 mm reichen. Alles bis etwa 50 x 38 mm bleibt unter der Preisgrenze.'],
      start: () => { const b = board('exled'); b.w = 100; b.h = 80; return b; }, sol: () => board('exled'),
      check(b) {
        const ref = board('exled'), c = CORE().cost(b, 10).perBoard, lim = CORE().cost(ref, 10).perBoard * 1.1;
        const edge = errsOf(b, ['unconnected']).filter(d => d.type === 'edge');
        return [L(c <= lim + 1e-9, 'Die Platine kostet für 10 Stück höchstens ' + f2(lim) + ' Euro je Stück', 'Deine Platine (' + f2(b.w, 1) + ' x ' + f2(b.h, 1) + ' mm) kostet ' + f2(c) + ' Euro je Stück, erlaubt sind ' + f2(lim) + ' Euro.'),
          L(edge.length === 0, 'Alles liegt im Umriss mit genug Randabstand', edge.length + ' Randverletzung(en): ' + msgs(edge, 1)), lnConn(b), lnShort(b), lnDrc(b), lnParts(b, DEF.exled())];
      } },

    /* ---------------- Bestückung */
    { id: 'pb28', lab: 'pcb', cat: 'Bestückung', title: 'Bestückungsreihenfolge festlegen', level: 2,
      text: 'Du bestückst die Netzteil-Platine von Hand. Lege die Reihenfolge fest, in der du die neun Bauteile einsetzt: zuerst die SMD-Teile (die werden gelötet, solange die Platine noch flach liegt), danach die bedrahteten Teile, und innerhalb der Gruppen die niedrigen Bauteile vor den hohen. Es müssen alle neun Bauteile in der Liste stehen.',
      hint: ['Die Platine muss beim Löten möglichst flach auf dem Tisch liegen. Hohe Teile stören, THT-Beine stören beim SMD-Löten.', 'Reihenfolge: erst alle SMD-Teile (R, C0805, LED, SOD-123), dann THT, vom niedrigsten zum höchsten. Der große Elko C1 kommt ganz zuletzt.', 'Beispiel: C2, D2, R1, D1, J2, U1, C3, J1, C1. Innerhalb gleich hoher Bauteile darfst du die Reihenfolge vertauschen.'],
      start: () => { const b = board('exnetz'), id = ASM() ? ASM().idealOrder(b) : b.parts.map(p => p.ref); return withAnswers(b, { order: id.slice().reverse() }); },
      sol: () => { const b = board('exnetz'); return withAnswers(b, { order: ASM().idealOrder(b) }); }, answer: [{ k: 'order', label: 'Reihenfolge der Bestückung (oben zuerst)', type: 'order', items: 'parts' }],
      check(b) {
        const S = ASM(); if (!S) return [L(false, 'Das Bestückungs-Modul ist nicht geladen', 'pcbasm.js fehlt.')];
        const ord = arr(A(b).order), r = S.orderScore(ord, b), grp = r.errors.filter(e => /\(THT\) steht vor/.test(e.why)), hgt = r.errors.filter(e => !/\(THT\) steht vor/.test(e.why));
        return [L(r.complete, 'Alle ' + b.parts.length + ' Bauteile stehen in der Liste', 'In deiner Liste stehen ' + r.placed + ' von ' + b.parts.length + ' Bauteilen.'),
          L(r.complete && grp.length === 0, 'Alle SMD-Teile kommen vor den bedrahteten Teilen', grp[0] ? grp[0].why : 'Die Liste ist noch nicht vollständig.'),
          L(r.complete && hgt.length === 0, 'Innerhalb der Gruppen kommen die niedrigen Teile zuerst', hgt[0] ? hgt[0].why : 'Die Liste ist noch nicht vollständig.'),
          L(r.score >= 95, 'Die Reihenfolge erreicht mindestens 95 Punkte', 'Deine Reihenfolge erreicht ' + r.score + ' von 100 Punkten.')];
      } },
    { id: 'pb29', lab: 'pcb', cat: 'Bestückung', title: 'Polarität: Diode, Elko und LED richtig herum', level: 2,
      text: 'Bei dieser Platine hat der Bestücker die Diode D1, den Elko C1 und die LED D2 jeweils um 180 Grad verdreht eingesetzt. Die Bahnen treffen die falschen Pads. Drehe die drei gepolten Bauteile richtig: Bei der Diode und der LED ist Pin 1 die Kathode (Strich), beim Elko ist Pin 1 der Pluspol. Danach muss alles verbunden und kurzschlussfrei sein.',
      hint: ['Gepolte Bauteile funktionieren nur in einer Richtung. Der Strich auf der Diode zeigt zur Kathode, beim Elko markiert der Streifen den Minuspol.', 'Auf der Platine ist Pin 1 der Diode im Plan mit VDC verbunden (Kathode am Pluspol der Versorgung), der Elko hat Plus an VDC. Prüfe bei jedem Teil, an welchem Netz Pin 1 liegt.', 'Drehe D1, C1 und D2 jeweils um 180 Grad zurück. Danach melden DRC und Netzliste keine offenen Verbindungen und keine Kurzschlüsse mehr.'],
      start: () => reflip(board('pol'), ['D1', 'C1', 'D2']), sol: () => board('pol'),
      check(b) {
        const c = connOf(b), P = padMap(b), out = [];
        ['D1', 'C1', 'D2'].forEach(r => {
          const open = c.unrouted.filter(u => (u.a && String(u.a.pad || '').split('.')[0] === r) || (u.b && String(u.b.pad || '').split('.')[0] === r)).length;
          const sh = c.shorts.filter(s => s.at && Object.keys(P).some(k => k.split('.')[0] === r && Math.hypot(P[k].x - s.at.x, P[k].y - s.at.y) < 2)).length;
          out.push(L(b.parts.some(p => p.ref === r) && open === 0 && sh === 0, r + ' sitzt richtig herum', r + ' ist falsch gepolt: Die Anschlüsse liegen an den falschen Bahnen. Pin 1 ist Kathode bzw. Pluspol.'));
        });
        out.push(lnConn(b)); out.push(lnShort(b)); out.push(lnDrc(b)); out.push(lnParts(b, DEF.pol()));
        return out;
      } },
    { id: 'pb30', lab: 'pcb', cat: 'Bestückung', title: 'Reflow-Profil einstellen', level: 3,
      text: 'Die LED-Treiber-Platine mit 19 SMD-Lötstellen kommt in den Reflow-Ofen (bleifreies Lot, Liquidus 217 °C). Stelle das Temperaturprofil so ein, dass alle Lötstellen gut werden: Aufheizen nicht zu steil, Soak zum Aktivieren des Flussmittels, Peak weit genug über dem Schmelzpunkt, aber nicht zu heiß, ausreichend Zeit über Liquidus, zügig abkühlen. Die Simulation darf keine Fehler (Zinnperlen, kalte Stellen, Überhitzung, Benetzungsfehler) melden.',
      hint: ['Jeder Fehler hat eine Ursache im Profil: zu steil macht Zinnperlen, zu kalt gibt kalte Stellen, zu heiß verbrennt das Flussmittel, zu langer Soak führt zu Benetzungsfehlern.', 'Typische Werte für bleifreies Lot: Aufheizen höchstens 3 °C/s, Soak 60 bis 120 s bis etwa 180 °C, Peak 235 bis 250 °C, 30 bis 90 s über 217 °C, Abkühlen mindestens 1 °C/s.', 'Zum Beispiel: Aufheizrate 2 °C/s, Soak 90 s bis 180 °C, Peak 245 °C, 60 s über Liquidus, Abkühlen 3 °C/s.'],
      start: () => { const S = ASM(); return withAnswers(board('exled'), S ? Object.assign({}, S.PROFILES.steil.p) : {}); }, sol: () => { const S = ASM(); return withAnswers(board('exled'), S ? Object.assign({}, S.PROFILES.standard.p) : {}); }, answer: PROF_ANS,
      check(b) {
        const S = ASM(); if (!S) return [L(false, 'Das Bestückungs-Modul ist nicht geladen', 'pcbasm.js fehlt.')];
        const p = profOf(A(b)), okNum = PROF_ANS.every(f => isFinite(p[f.k]));
        if (!okNum) return [L(false, 'Alle Profilwerte sind eingetragen', 'Trage alle sechs Werte als Zahlen ein.')];
        const w = S.profileCheck(p).warnings, bad = w.filter(x => x.level === 'bad'), warn = w.filter(x => x.level === 'warn'), r = S.reflow(b, p, { seed: 1 }), n = r.joints.length, g = r.joints.filter(j => j.result === 'gut').length;
        return [L(bad.length === 0, 'Kein Wert ist im kritischen Bereich', bad.map(x => x.text).slice(0, 2).join(' ')), L(warn.length === 0, 'Alle Werte liegen im üblichen Bereich', warn.map(x => x.text).slice(0, 2).join(' ')),
          L(n > 0 && g === n, 'Alle ' + n + ' Lötstellen werden gut', (n - g) + ' von ' + n + ' Lötstellen sind fehlerhaft. ' + (r.warnings && r.warnings[0] ? (r.warnings[0].text || r.warnings[0]) : '')), L(!!r.ok, 'Der Reflow-Lauf ist insgesamt in Ordnung', 'Die Simulation meldet noch Fehler.')];
      } },

    /* ---------------- Löten */
    { id: 'pb31', lab: 'pcb', cat: 'Löten', title: 'Handlöten: Widerstand THT', level: 2,
      text: 'Du lötest einen bedrahteten Widerstand von Hand. Wähle Lötspitze, Temperatur, Heizzeit und Lotmenge so, dass die Lötstelle eine Qualität von mindestens 85 Punkten erreicht und keinen Fehler zeigt. Der Ablauf ist fest: Pad und Anschluss erwärmen, Lot zuführen, Lot wegnehmen, Kolben wegnehmen.',
      hint: ['Das Pad muss heiß genug sein, bevor das Lot kommt. Zu viel Hitze lässt das Pad abheben, zu wenig gibt eine kalte Lötstelle.', 'Für THT passen Temperaturen um 330 bis 350 °C, 3 bis 4 s Heizzeit, eine Meißel- oder Kegelspitze und etwa 4 mm Lötdraht.', 'Meißelspitze, 340 °C, 3,5 s Heizzeit, 4 mm Lot.'],
      start: () => withAnswers(board('exled'), { tip: 'fein', temp: 450, time: 9, wireMm: 8 }), sol: () => withAnswers(board('exled'), { tip: 'meissel', temp: 340, time: 3.5, wireMm: 4 }),
      answer: [{ k: 'tip', label: 'Lötspitze', type: 'select', options: TIP_OPTS }, { k: 'temp', label: 'Kolbentemperatur', unit: '°C', type: 'num', min: 200, max: 450, step: 5 }, { k: 'time', label: 'Heizzeit', unit: 's', type: 'num', min: 0.5, max: 12, step: 0.5 }, { k: 'wireMm', label: 'Länge des Lötdrahts', unit: 'mm', type: 'num', min: 0, max: 12, step: 0.5 }],
      check(b) { return handLines(b, 'tht', ['tip', 'temp', 'time', 'wireMm'], {}); } },
    { id: 'pb32', lab: 'pcb', cat: 'Löten', title: 'Handlöten: SOIC mit Schleppen', level: 3,
      text: 'Du lötest ein SOIC-Gehäuse (Pinabstand 1,27 mm) im Schleppverfahren: Der Kolben gleitet mit Lot an der Pinreihe entlang. Wähle Spitze, Temperatur, Schleppgeschwindigkeit und Lotmenge so, dass die Lötstellen mindestens 85 Punkte erreichen und keine Brücke zwischen den Pins entsteht.',
      hint: ['Beim Schleppen bringt das Lot die Wärme zum Pad. Zu schnell: kaum Lot, kein Kontakt. Zu langsam oder zu viel Lot: Brücken.', 'Eine Messerspitze (zum Schleppen) mit etwa 330 bis 350 °C, einer Geschwindigkeit um 5 mm/s und rund 1 bis 1,5 mm Lot je Stelle.', 'Messerspitze, 340 °C, 5 mm/s Schleppgeschwindigkeit, 1,2 mm Lot.'],
      start: () => withAnswers(board('exled'), { tip: 'meissel', temp: 400, drag: 1.5, wireMm: 4 }), sol: () => withAnswers(board('exled'), { tip: 'messer', temp: 340, drag: 5, wireMm: 1.2 }),
      answer: [{ k: 'tip', label: 'Lötspitze', type: 'select', options: TIP_OPTS }, { k: 'temp', label: 'Kolbentemperatur', unit: '°C', type: 'num', min: 200, max: 450, step: 5 }, { k: 'drag', label: 'Schleppgeschwindigkeit', unit: 'mm/s', type: 'num', min: 0.5, max: 12, step: 0.5 }, { k: 'wireMm', label: 'Lotmenge je Lötstelle', unit: 'mm', type: 'num', min: 0, max: 6, step: 0.1 }],
      check(b) { return handLines(b, 'soic', ['tip', 'temp', 'drag', 'wireMm'], {}); } },

    /* ---------------- Fehlersuche */
    { id: 'pb33', lab: 'pcb', cat: 'Fehlersuche', title: 'Der Blinker blinkt nicht', level: 1,
      text: 'Der 555-Blinker leuchtet nicht, obwohl optisch alles in Ordnung aussieht. Prüfe mit dem Durchgangsprüfer die Netze und der Lupe die Platine, finde die Ursache und repariere sie. Arbeite im Fehlersuche-Tab.',
      hint: ['Fehlersuche heißt: erst messen, dann reparieren. Ein Netz muss von Pad zu Pad Durchgang haben.', 'Miss die Netze nacheinander mit dem Durchgangsprüfer. Das Netz, bei dem der Piepton fehlt, enthält den Riss. Mit der Lupe findest du ihn auf der Unterseite.', 'Der Riss liegt in einer Bahn der Unterseite. Überbrücke ihn mit Lötzinn oder lege einen Fädeldraht über die Stelle.'],
      start: () => repStart('ex555', [['crack', 1]]), sol: () => repSol(repStart('ex555', [['crack', 1]])), check: b => repLines(b) },
    { id: 'pb34', lab: 'pcb', cat: 'Fehlersuche', title: 'Das Netzteil bricht zusammen', level: 1,
      text: 'Das Netzteil liefert keine saubere Spannung und bricht unter Last zusammen. Prüfe die Platine anhand des Schaltplans mit Lupe und Messgerät, finde die Ursache und behebe sie. Arbeite im Fehlersuche-Tab.',
      hint: ['Gepolte Bauteile sind Elkos, Dioden und LEDs. Prüfe, wohin Plus und Minus laut Plan gehören.', 'Schau dir die Bauteile in der Lupe an und vergleiche die Markierung mit dem Schaltplan. Das Bauteil, das nicht zur Polung passt, ist falsch eingebaut.', 'Löte das verpolte Bauteil aus und setze es um 180 Grad gedreht wieder ein (Werkzeug Drehen am Lötkolben).'],
      start: () => repStart('exnetz', [['reversed', 1]]), sol: () => repSol(repStart('exnetz', [['reversed', 1]])), check: b => repLines(b) },
    { id: 'pb35', lab: 'pcb', cat: 'Fehlersuche', title: 'Der LED-Treiber wird warm', level: 2,
      text: 'Die LED-Treiber-Platine zieht zu viel Strom und wird warm. Suche mit dem Widerstandsmessgerät und der Lupe die Ursache und beseitige sie. Arbeite im Fehlersuche-Tab.',
      hint: ['Ein Kurzschluss zwischen zwei Netzen zeigt sich als Durchgang dort, wo keiner sein soll.', 'Prüfe die Netze gegeneinander: Zeigt das Messgerät zwischen zwei verschiedenen Netzen Durchgang, sitzt irgendwo dazwischen Lot. Die Lupe zeigt dir die Stelle bei eng liegenden Pads.', 'Lötbrücken saugst du mit der Entlötlitze weg. Pinzette und Messer sind für Zinnperlen und Kupferreste.'],
      start: () => repStart('exled', [['bridge', 1]]), sol: () => repSol(repStart('exled', [['bridge', 1]])), check: b => repLines(b) },
    { id: 'pb36', lab: 'pcb', cat: 'Fehlersuche', title: 'Die Platine läuft nur beim Antippen', level: 2,
      text: 'Die LED-Treiber-Platine funktioniert nur, wenn du sie leicht antippst. Prüfe mit der Lupe die Platine, finde die Ursache und behebe sie. Arbeite im Fehlersuche-Tab.',
      hint: ['Eine kalte Lötstelle sieht matt und körnig aus und leitet nur manchmal.', 'Schau mit der Lupe alle Lötstellen an. Die schlechte Stelle glänzt nicht und hat keinen sauberen Meniskus. Messen hilft hier nur zufällig, weil der Kontakt wackelt.', 'Mit dem Lötkolben die Stelle nachlöten (Reflow der Lötstelle). Danach glänzt sie wieder.'],
      start: () => repStart('exled', [['cold', 1]]), sol: () => repSol(repStart('exled', [['cold', 1]])), check: b => repLines(b) },
    { id: 'pb37', lab: 'pcb', cat: 'Fehlersuche', title: 'Das Netzteil läuft nur beim Biegen', level: 3,
      text: 'Das Netzteil funktioniert nur, wenn du die Platine biegst. Finde die Stelle durch Messen von Pad zu Pad auf beiden Seiten der Platine und repariere sie. Arbeite im Fehlersuche-Tab.',
      hint: ['Ein Via verbindet Ober- und Unterseite. Ist die Kupferhülse gebrochen, haben die Seiten keinen Durchgang mehr.', 'Miss das Netz, das ein Via enthält, getrennt auf der Oberseite und auf der Unterseite. Wo der Durchgang nach dem Via fehlt, ist es gebrochen.', 'Mit dem Werkzeug Draht durch das Via löten (Via reparieren). Der Fehler ist danach behoben.'],
      start: () => repStart('exnetz', [['viabreak', 1]]), sol: () => repSol(repStart('exnetz', [['viabreak', 1]])), check: b => repLines(b) },
    { id: 'pb38', lab: 'pcb', cat: 'Fehlersuche', title: 'Der Vorverstärker verstärkt zu wenig', level: 2,
      text: 'Der OPV-Vorverstärker verstärkt viel zu wenig. Miss die Bauteile im ausgeschalteten Zustand (Widerstandsmessung), vergleiche mit Schaltplan und Stückliste, finde die Ursache und behebe sie. Arbeite im Fehlersuche-Tab.',
      hint: ['Widerstände misst du aus dem Stromkreis oder ausgelötet. Vergleiche den Messwert mit dem Soll aus dem Schaltplan.', 'Miss die Widerstände nacheinander. Einer weicht stark vom Sollwert ab (zum Beispiel 1 kOhm statt 10 kOhm). Das ist der falsche.', 'Bauteil austauschen (Löten, Bauteil tauschen) und den Sollwert aus dem Schaltplan eintragen.'],
      start: () => repStart('exopv', [['wrongvalue', 1]]), sol: () => repSol(repStart('exopv', [['wrongvalue', 1]])), check: b => repLines(b) },

    /* ---------------- Prüfverfahren */
    { id: 'pb39', lab: 'pcb', cat: 'Prüfverfahren', title: 'Prüfaufwand aus der Netzliste berechnen', level: 2,
      text: 'Ein Flying-Probe-Tester prüft den LED-Treiber: Er kontaktiert die Pins eines Netzes nacheinander und misst auf Durchgang, es sind also (Pinzahl - 1) Messungen je Netz. Bestimme aus der Netzliste dieser Platine: wie viele Netze (mit mindestens zwei Pins) es gibt, wie viele Pins insgesamt in diesen Netzen liegen, und wie viele Durchgangsmessungen nötig sind. Eine Messung dauert 0,2 s: Wie lange dauert die Prüfung einer Platine (in Sekunden, auf 0,1 s)?',
      hint: ['Die Netzliste steht im Netz-Dialog: Zu jedem Netz gehört eine Pinliste.', 'Zähle Netze und Pins. Je Netz brauchst du (Pins - 1) Messungen, um alle Pins zu verbinden.', 'Netze: 8, Pins: 23, Messungen: 23 - 8 = 15, Zeit: 15 · 0,2 s = 3,0 s.'],
      start: () => withAnswers(board('exled'), {}), sol: () => { const b = board('exled'), f = pruefWerte(b); return withAnswers(b, { nets: f.nets, pins: f.pins, meas: f.meas, time: f.time }); },
      answer: [{ k: 'nets', label: 'Anzahl der Netze mit mindestens 2 Pins', type: 'num', min: 0, max: 99, step: 1 }, { k: 'pins', label: 'Pins in diesen Netzen insgesamt', type: 'num', min: 0, max: 999, step: 1 }, { k: 'meas', label: 'Durchgangsmessungen je Platine', type: 'num', min: 0, max: 999, step: 1 }, { k: 'time', label: 'Prüfzeit je Platine', unit: 's', type: 'num', min: 0, max: 999, step: 0.1 }],
      check(b) {
        const f = pruefWerte(b), a = A(b), w = (k, lab, tol, hint) => L(near(a[k], f[k], tol), lab, a[k] === undefined || a[k] === '' ? 'Hier fehlt noch deine Antwort.' : 'Dein Wert ' + a[k] + ' stimmt nicht. ' + hint);
        return [w('nets', 'Zahl der Netze mit mindestens 2 Pins', 0, 'Zähle die Netze im Netz-Dialog.'), w('pins', 'Zahl der Pins in diesen Netzen', 0, 'Zähle alle Pins aller Netze zusammen.'), w('meas', 'Zahl der Durchgangsmessungen', 0, 'Je Netz: Pinzahl minus 1, dann alles addieren.'), w('time', 'Prüfzeit je Platine', 0.05, 'Zeit = Messungen mal 0,2 s.')];
      } },
    { id: 'pb40', lab: 'pcb', cat: 'Prüfverfahren', title: 'Nadelbettadapter oder Flying Probe: ab wann lohnt es sich?', level: 3,
      text: 'Ein Nadelbettadapter kostet einmalig 1800 Euro, danach kostet die Prüfung 0,40 Euro je Platine. Ein Flying-Probe-Tester braucht keinen Adapter, die Prüfung kostet aber 3,50 Euro je Platine. Berechne die Gesamtkosten für 200 Platinen bei beiden Verfahren (in Euro) und die kleinste Stückzahl, ab der der Nadelbettadapter günstiger ist als Flying Probe. Wähle außerdem das günstigere Verfahren für 1000 Platinen.',
      hint: ['Gesamtkosten = Fixkosten + Stückzahl mal Kosten je Platine. Der Break-even ist die Stückzahl, bei der beide gleich sind.', 'Setze gleich: 1800 + 0,40 · n = 3,50 · n. Löse nach n auf und runde auf, denn bei der exakten Zahl ist der Adapter noch nicht günstiger.', '200 Stück: Nadelbett 1800 + 80 = 1880 Euro, Flying Probe 700 Euro. Break-even: 1800 / 3,10 = 580,6, also ab 581 Platinen. Für 1000 Platinen ist das Nadelbett günstiger.'],
      start: () => withAnswers(board('exled'), {}), sol: () => withAnswers(board('exled'), { nb200: 1880, fp200: 700, be: 581, best1000: 'Nadelbettadapter' }),
      answer: [{ k: 'nb200', label: 'Kosten Nadelbettadapter für 200 Platinen', unit: 'Euro', type: 'num', min: 0, max: 99999, step: 1 }, { k: 'fp200', label: 'Kosten Flying Probe für 200 Platinen', unit: 'Euro', type: 'num', min: 0, max: 99999, step: 1 }, { k: 'be', label: 'Break-even-Stückzahl (Adapter ab hier günstiger)', type: 'num', min: 0, max: 99999, step: 1 }, { k: 'best1000', label: 'Günstigeres Verfahren bei 1000 Platinen', type: 'select', options: [['Nadelbettadapter', 'Nadelbettadapter'], ['Flying Probe', 'Flying Probe']] }],
      check(b) {
        const a = A(b), bad = k => (a[k] === undefined || a[k] === '' ? 'Hier fehlt noch deine Antwort.' : 'Dein Wert ' + a[k] + ' stimmt nicht.');
        return [L(near(a.nb200, 1880, 0.5), 'Nadelbett, 200 Stück: 1880 Euro', bad('nb200') + ' Rechne 1800 + 200 · 0,40.'), L(near(a.fp200, 700, 0.5), 'Flying Probe, 200 Stück: 700 Euro', bad('fp200') + ' Rechne 200 · 3,50.'),
          L(near(a.be, 581, 0.5), 'Break-even bei 581 Platinen', bad('be') + ' Rechne 1800 / (3,50 - 0,40) und runde auf.'), L(a.best1000 === 'Nadelbettadapter', 'Bei 1000 Platinen gewinnt der Nadelbettadapter', bad('best1000') + ' Vergleiche 1800 + 400 mit 3500.')];
      } },

    { id: 'pb41', lab: 'pcb', cat: 'Prüfverfahren', title: 'Testpunkte ergänzen: Flying-Probe-Abdeckung erhöhen', level: 3,
      text: 'Die Flying-Probe-Prüfung (Nadeln nur von oben) erreicht bei dieser Platine nur etwa 69 Prozent Abdeckung: Die USB-Datenleitungen DM und DP laufen nur auf der Unterseite zwischen den Stiftleisten und haben keinen erreichbaren Prüfpunkt. Ergänze Testpunkte, am einfachsten Vias im jeweiligen Netz auf der Leitung, die nicht unter einem Bauteil liegen. Danach soll die Abdeckung mindestens 85 Prozent betragen und jedes Netz mindestens einen erreichbaren Prüfpunkt haben. Der DRC muss sauber bleiben, setze nicht mehr als 8 zusätzliche Vias.',
      hint: ['Der Tester setzt zwei Nadeln auf Kupfer, das von oben frei zugänglich ist. Pins von Stiftleisten zählen nicht, ihre Lötseite liegt unten und das Bauteil steht im Weg.', 'Ein Via auf der Bahn ist von oben erreichbar, wenn es nicht unter einem Bauteil liegt und nicht zu nah an einem hohen Bauteil. Für eine Durchgangsmessung brauchst du je Netz zwei Prüfpunkte.', 'Setze je zwei Vias (0,8 mm) auf DM und auf DP, zum Beispiel bei x = 12 mm und x = 40 mm, im Netz DM bzw. DP. Prüfe danach die Abdeckung in der Flying-Probe-Ansicht.'],
      start: () => board('exusb'),
      sol: () => { const b = board('exusb'); [['DM', 12, 15.75], ['DM', 40, 15.75], ['DP', 12, 18.25], ['DP', 40, 18.25]].forEach((a, i) => b.vias.push({ id: 'tv' + (i + 1), x: a[1], y: a[2], net: a[0], dia: 0.8, drill: 0.4, from: 'F.Cu', to: 'B.Cu' })); return b; },
      check(b) {
        const T = root.PCB_TEST; if (!T || !T.planFlyingProbe) return [L(false, 'Das Prüf-Modul ist nicht geladen', 'pcbtest.js fehlt.')];
        const r = T.planFlyingProbe(b), cov = r.coverage || {}, notp = arr(r.issues).filter(i => i.type === 'notp'), extra = b.vias.length - board('exusb').vias.length;
        return [L(cov.pct >= 85, 'Die Flying-Probe-Abdeckung beträgt mindestens 85 %', 'Die Abdeckung liegt bei ' + f2(cov.pct || 0, 0) + ' %. Es fehlen erreichbare Prüfpunkte.'),
          L(notp.length === 0, 'Jedes Netz hat einen erreichbaren Prüfpunkt', notp.length + ' Netz(e) ohne Prüfpunkt, zum Beispiel: ' + msgs(notp, 1)),
          L(extra <= 8, 'Nicht mehr als 8 zusätzliche Vias', 'Du hast ' + extra + ' zusätzliche Vias gesetzt.'), lnConn(b), lnShort(b), lnDrc(b), lnNets(b, DEF.exusb())];
      } },

    /* ---------------- Prüfungsstil */
    { id: 'pb42', lab: 'pcb', cat: 'Prüfungsstil', title: 'Prüfungsaufgabe: Heizungssteuerung, Bahnbreite und Spannungsabfall', level: 2,
      text: 'Auf der Platine einer Heizungssteuerung führt eine 120 mm lange Leiterbahn auf der Außenlage (Kupfer 1 oz = 35 µm) den Laststrom von 2,5 A. a) Wie breit muss die Bahn nach IPC-2221 bei 10 K Erwärmung mindestens sein (in mm, auf 0,01 mm)? Du wählst dann 1,5 mm. b) Welchen Widerstand hat die 1,5 mm breite Bahn (in mOhm; ρ Kupfer = 1,72 · 10^-8 Ohm · m, der Tabellenbuchwert 0,0178 Ohm · mm²/m ist ebenso in Ordnung)? c) Wie groß ist der Spannungsabfall bei 2,5 A (in mV)? d) Welche Verlustleistung entsteht in der Bahn (in mW)?',
      hint: ['Die Mindestbreite liefert der Netz-Dialog oder die IPC-Formel. Für den Widerstand brauchst du R = ρ · l / A mit A = Breite · Dicke.', 'A = 1,5 mm · 0,035 mm = 0,0525 mm² = 5,25 · 10^-8 m². R = 1,72 · 10^-8 · 0,12 / 5,25 · 10^-8. Danach U = I · R und P = I² · R.', 'a) 1,06 mm. b) R = 39,3 mOhm. c) U = 2,5 A · 39,3 mOhm = 98,3 mV. d) P = 2,5² · 39,3 mOhm = 246 mW.'],
      start: () => withAnswers(board('exled'), {}), sol: () => { const v = rechne41(); return withAnswers(board('exled'), { w: v.w, r: v.r, u: v.u, p: v.p }); },
      answer: [{ k: 'w', label: 'a) Mindestbreite für 2,5 A', unit: 'mm', type: 'num', min: 0, max: 20, step: 0.01 }, { k: 'r', label: 'b) Widerstand der 1,5-mm-Bahn', unit: 'mOhm', type: 'num', min: 0, max: 9999, step: 0.1 }, { k: 'u', label: 'c) Spannungsabfall bei 2,5 A', unit: 'mV', type: 'num', min: 0, max: 9999, step: 0.1 }, { k: 'p', label: 'd) Verlustleistung', unit: 'mW', type: 'num', min: 0, max: 99999, step: 1 }],
      check(b) {
        const v = rechne41(), a = A(b), bad = k => (a[k] === undefined || a[k] === '' ? 'Hier fehlt noch deine Antwort.' : 'Dein Wert ' + a[k] + ' stimmt nicht.');
        return [L(near(a.w, v.w, 0.03), 'a) Mindestbreite etwa ' + f2(v.w) + ' mm', bad('w') + ' Nimm 2,5 A, 1 oz, außen, 10 K im Netz-Dialog oder in der IPC-Formel.'), /* Toleranzen so, dass auch der Tabellenbuchwert ρ = 0,0178 Ω·mm²/m (ergibt 40,7 mOhm) besteht */
          L(near(a.r, v.r, 2), 'b) Widerstand etwa ' + f2(v.r, 1) + ' mOhm', bad('r') + ' R = ρ · l / (b · d) mit l = 120 mm, b = 1,5 mm, d = 0,035 mm.'),
          L(near(a.u, v.u, 5), 'c) Spannungsabfall etwa ' + f2(v.u, 1) + ' mV', bad('u') + ' U = I · R.'), L(near(a.p, v.p, 15), 'd) Verlustleistung etwa ' + f2(v.p, 0) + ' mW', bad('p') + ' P = I² · R.')];
      } },
    { id: 'pb43', lab: 'pcb', cat: 'Prüfungsstil', title: 'Prüfungsaufgabe: Schaltplan und Layout des USB-Netzteils', level: 2,
      text: 'Gegeben ist die Platine des USB-Netzteils (Beispiel "USB-Netzteil 3,3 V"). Beantworte aus Netzliste und Platinendaten: a) Wie viele Netze der Klasse Versorgung (power) gibt es? b) Wie viele Vias hat die Platine? c) Das Netz VBUS führt 0,5 A: Welche Mindestbreite verlangt IPC-2221 (1 oz, außen, 10 K, in mm auf 0,01 mm)? d) Welche Breite wählst du, wenn der Hersteller mindestens 0,2 mm verlangt (der größere der beiden Werte)? e) Wie viele Lagen hat die Platine?',
      hint: ['Die Netzklassen und der Strom stehen im Netz-Dialog, die Vias findest du im Layout (Zählen oder Filter).', 'Die IPC-Mindestbreite für 0,5 A ist klein. Die Fertigung setzt aber eine Untergrenze: Du nimmst immer den größeren der beiden Werte.', 'a) 4 (VBUS, VIN, GND, V33). b) Zahl der Vias der Platine. c) 0,12 mm. d) 0,2 mm. e) 2 Lagen.'],
      start: () => withAnswers(board('exusb'), {}), sol: () => { const b = board('exusb'), f = werte42(b); return withAnswers(b, { pw: f.pw, via: f.via, wmin: f.wmin, wsel: f.wsel, lay: f.lay }); },
      answer: [{ k: 'pw', label: 'a) Netze der Klasse Versorgung', type: 'num', min: 0, max: 99, step: 1 }, { k: 'via', label: 'b) Anzahl der Vias', type: 'num', min: 0, max: 999, step: 1 }, { k: 'wmin', label: 'c) IPC-Mindestbreite für 0,5 A', unit: 'mm', type: 'num', min: 0, max: 10, step: 0.01 }, { k: 'wsel', label: 'd) gewählte Breite (Hersteller mindestens 0,2 mm)', unit: 'mm', type: 'num', min: 0, max: 10, step: 0.01 }, { k: 'lay', label: 'e) Anzahl der Lagen', type: 'num', min: 1, max: 6, step: 1 }],
      check(b) {
        const f = werte42(b), a = A(b), bad = k => (a[k] === undefined || a[k] === '' ? 'Hier fehlt noch deine Antwort.' : 'Dein Wert ' + a[k] + ' stimmt nicht.');
        return [L(near(a.pw, f.pw, 0), 'a) Versorgungsnetze: ' + f.pw, bad('pw') + ' Zähle im Netz-Dialog die Netze der Klasse Versorgung.'), L(near(a.via, f.via, 0), 'b) Vias: ' + f.via, bad('via') + ' Zähle die Vias im Layout.'),
          L(near(a.wmin, f.wmin, 0.015), 'c) IPC-Mindestbreite etwa ' + f2(f.wmin) + ' mm', bad('wmin') + ' 0,5 A, 1 oz, außen, 10 K Erwärmung.'), L(near(a.wsel, f.wsel, 0.005), 'd) gewählte Breite ' + f2(f.wsel) + ' mm', bad('wsel') + ' Nimm den größeren Wert aus IPC und Herstellerminimum.'), L(near(a.lay, f.lay, 0), 'e) Lagen: ' + f.lay, bad('lay') + ' Die Lagenzahl steht in den Platinen-Eigenschaften.')];
      } }
  ];

  /* ---- Rechenhilfen der Wissensaufgaben */
  function pruefWerte(b) {
    const ns = arr(b.nets).filter(n => arr(n.pins).length >= 2), pins = ns.reduce((s, n) => s + n.pins.length, 0), meas = pins - ns.length;
    return { nets: ns.length, pins, meas, time: Math.round(meas * 0.2 * 10) / 10 };
  }
  function rechne41() {
    const C = CORE(), w = Math.round(C.ipcWidth(2.5, { oz: 1, rise: 10, external: true }) * 100) / 100, R = C.traceResistance(120, 1.5, 1);
    return { w, r: Math.round(R * 10000) / 10, u: Math.round(2.5 * R * 10000) / 10, p: Math.round(6.25 * R * 10000) / 10 };
  }
  function werte42(b) {
    const C = CORE(), wmin = Math.round(C.ipcWidth(0.5, { oz: b.copperOz || 1, rise: 10, external: true }) * 100) / 100;
    return { pw: arr(b.nets).filter(n => n.cls === 'power').length, via: arr(b.vias).length, wmin, wsel: Math.max(wmin, 0.2), lay: +b.layers };
  }
  /* Handlöten: Parameter aus dem Antwortblatt in das Modell geben */
  function handLines(b, kind, keys, extra) {
    const S = ASM(); if (!S) return [L(false, 'Das Bestückungs-Modul ist nicht geladen', 'pcbasm.js fehlt.')];
    const a = A(b), p = Object.assign({ kind, seed: 1 }, extra || {});
    for (let i = 0; i < keys.length; i++) { const k = keys[i], v = a[k]; if (k === 'tip') { if (!v) return [L(false, 'Alle Werte sind eingetragen', 'Wähle eine Lötspitze.')]; p.tip = v; } else { const n = num(v); if (!isFinite(n)) return [L(false, 'Alle Werte sind eingetragen', 'Trage alle Werte als Zahlen ein.')]; p[k] = n; } }
    const r = S.handSolder(p), d = r.defects || [], dn = d.map(x => (typeof x === 'string' ? x : x.id));
    const nn = (r.notes || []).slice(0, 2).join(' ');
    return [L(r.quality >= 85, 'Die Qualität der Lötstelle liegt bei mindestens 85 Punkten', 'Deine Lötstelle erreicht ' + Math.round(r.quality) + ' Punkte. ' + nn), L(dn.length === 0, 'Die Lötstelle zeigt keinen Fehler', 'Fehler: ' + dn.join(', ') + '. ' + nn)];
  }

  const run = (task, b0) => new Promise(res => {
    try {
      const b = sane(b0 ? clone(b0) : null);
      if (!b) { res([L(false, 'Es liegt keine Platine vor', 'Öffne die Aufgabe neu, damit du eine Startplatine bekommst.')]); return; }
      if (!CORE()) { res([L(false, 'Der Platinen-Kern ist nicht geladen', 'pcbcore.js fehlt.')]); return; }
      const v = CORE().validate(b);
      if (v && v.ok === false) { res([L(false, 'Die Platine hat Modellfehler', arr(v.errors).slice(0, 3).join(' | '))]); return; }
      const lines = task.check(b);
      res(Array.isArray(lines) ? lines : []);
    } catch (e) { res([{ ok: false, text: 'Die Prüfung konnte nicht ausgeführt werden', why: String(e && e.message || e) }]); }
  });


  /* ====================================================================== Beispiele */
  const named = (b, name) => { b.name = name; return b; };
  const EX = [
    ['ex555', 'Einsteiger', '555-Blinker, einseitig (THT)', 'Der Klassiker auf einer einseitigen Platine: NE555 als Rechteckgenerator, zwei Widerstände und ein Elko bestimmen die Blinkfrequenz, eine LED zeigt sie an. Alle Bauteile sind bedrahtet und sitzen oben, die Bahnen liegen komplett auf der Lötseite. Gut zum Üben von Raster, Pads und Lötstellen.', () => board('ex555')],
    ['exled', 'Einsteiger', 'LED-Treiber (SMD)', 'Ein Transistor schaltet drei LEDs mit je einem Vorwiderstand. Alle Bauteile sind SMD (0603, 0805, SOT-23), die Platine hat zwei Lagen, aber alle Bahnen liegen oben. Gut, um kleine Footprints, Pads und das Reflow-Löten kennenzulernen.', () => board('exled')],
    ['exnetz', 'Einsteiger', 'Netzteil 5 V mit LM7805 (THT und SMD gemischt)', 'Ein Festspannungsregler LM7805 macht aus 9 V stabile 5 V. Die Versorgungsnetze führen 1 A und sind deshalb breiter als die Signalbahn zur LED. Die Platine mischt THT (Buchse, Elkos, Regler) und SMD (Diode, 0805, 0603) und zeigt, wie man beides in einem Durchgang bestückt.', () => board('exnetz')],
    ['exnetzsmd', 'Einsteiger', 'Netzteil 5 V mit AMS1117 (SMD)', 'Dasselbe Netzteil mit einem SMD-Regler im SOT-223-Gehäuse. Die Kühlfahne des Reglers (Pin 4) liegt auf dem Ausgang und dient als Kühlfläche. Die Versorgungsbahnen sind für 1 A ausgelegt.', () => board('exnetzsmd')],
    ['exshield', 'Einsteiger', 'Arduino-Shield mit Tastern und LEDs', 'Ein Aufsteck-Board mit zwei Tastern (mit Pull-up-Widerständen) und zwei LEDs mit Vorwiderständen. Die Stiftleisten bringen Digitalsignale und Versorgung vom Arduino. Vereinfachtes Layout im Format eines Arduino Uno (68,6 x 53,3 mm).', () => board('exshield')],
    ['exusb', 'Einsteiger', 'USB-Netzteil 3,3 V', 'Ein Linearregler macht aus den 5 V des USB-Anschlusses 3,3 V. Eine Sicherung schützt den Anschluss, Elkos und ein Keramikkondensator glätten. Die Datenleitungen D- und D+ laufen unverändert zur Ausgangsleiste durch.', () => board('exusb')],
    ['exopv', 'Einsteiger', 'OPV-Vorverstärker mit Massefläche', 'Ein nichtinvertierender Verstärker mit LM358 an einer Einzelspannung von 5 V. Die Signalwege liegen oben, die Unterseite ist eine durchgehende Massefläche, an die jedes GND-Pad per Via angeschlossen ist. Eingang und Ausgang liegen auf gegenüberliegenden Seiten, damit der Verstärker nicht schwingt.', () => board('exopv')],
    ['exmotor', 'Einsteiger', 'Motortreiber mit H-Brücke (breite Bahnen)', 'Vier MOSFETs im TO-220-Gehäuse steuern einen Gleichstrommotor in beide Richtungen. Der Motorstrom von 3 A erzwingt breite Bahnen (mindestens 1,37 mm nach IPC-2221). Die Steuersignale kommen über Gate-Widerstände an die Transistoren.', () => board('exmotor')],
    ['exsensor', 'Mehrlagen', 'Sensorknoten mit Mikrocontroller (4 Lagen)', 'Ein Mikrocontroller im QFP-32-Gehäuse mit Quarz, I2C-Sensoranschluss, Programmierstecker und 3,3-V-Regler. Die Lagen sind Signal, Masse (In1), Versorgung (In2), Signal: GND und VCC kommen mit kurzen Vias an die Flächen, jeder Versorgungspin des Controllers hat einen Abblockkondensator in der Nähe.', () => board('exsensor')],
    ['exiface', 'Mehrlagen', 'Schnittstellenplatine mit RS-485 und CAN (6 Lagen)', 'Ein Mikrocontroller mit RS-485- und CAN-Transceiver auf einer 6-Lagen-Platine: Signal, Masse (In1), zwei innere Signallagen, Versorgung (In4), Signal. Die Innenlagen In2 und In3 nehmen die Querverbindungen auf, die Ebenen bleiben ungestört.', () => board('exiface')],
    ['ex_err_abstand', 'DRC-Fehler zum Beheben', 'Fehlerbeispiel: Abstand zu klein', 'Zwei Signalbahnen liegen nur 0,1 mm auseinander, der Mindestabstand ist 0,2 mm. Beim Ätzen oder Löten kann dort ein Kurzschluss entstehen. Finde die Stelle mit dem DRC und schiebe die Bahn weg.', () => named(board('h2_abst'), 'Fehlerbeispiel: Abstand zu klein')],
    ['ex_err_kurz', 'DRC-Fehler zum Beheben', 'Fehlerbeispiel: Kurzschluss und offene Verbindung', 'Eine Bahn kreuzt eine fremde Bahn (Kurzschluss), und im Netz VCC fehlt eine Verbindung (Luftlinie). Beide Fehler meldet der DRC. Behebe sie beide, ohne die Regeln zu lockern.', () => named(board('h2_kurz'), 'Fehlerbeispiel: Kurzschluss und Luftlinie')],
    ['ex_err_strom', 'DRC-Fehler zum Beheben', 'Fehlerbeispiel: Strom, Breite und Rand', 'Die Versorgungsbahnen sind für 2 A zu schmal, eine Signalbahn unterschreitet die Mindestbreite, und eine Bahn liegt zu nah am Platinenrand. Drei Fehlerarten auf einer Platine: Lies die DRC-Meldungen genau.', () => named(setCur(board('h2_schmal'), { VCC: 2, GND: 2 }), 'Fehlerbeispiel: Strom, Breite, Rand')],
    ['ex_err_via', 'DRC-Fehler zum Beheben', 'Fehlerbeispiel: Via-Bohrung und Restring', 'Zwei Vias passen nicht zu den Fertigungsregeln: Beim einen bleibt nur 0,05 mm Kupferring, beim anderen ist die Bohrung mit 0,2 mm zu fein. Ändere die Via-Maße, bis der DRC sauber ist.', () => named(viasBad(board('h3')), 'Fehlerbeispiel: Via-Maße')],
    ['ex_err_flaeche', 'DRC-Fehler zum Beheben', 'Fehlerbeispiel: Takt zerschneidet die Massefläche', 'Die Taktleitung läuft auf der Unterseite quer durch die GND-Fläche. Der DRC meldet einen Flächenschnitt (Warnung): Der Rückstrom muss einen Umweg nehmen. Lege die Leitung auf die Gegenlage.', () => named(board('h6'), 'Fehlerbeispiel: Flächenschnitt')],
    ['ex_rep_haarriss', 'Fehlersuche (Reparatur)', 'Reparatur: Haarriss im 555-Blinker', 'Der Blinker bleibt dunkel, weil eine Leiterbahn auf der Unterseite einen feinen Riss hat. Finde ihn mit dem Durchgangsprüfer und der Lupe und überbrücke ihn.', () => named(repStart('ex555', [['crack', 1]]), 'Reparatur: Haarriss')],
    ['ex_rep_polung', 'Fehlersuche (Reparatur)', 'Reparatur: verpoltes Bauteil im Netzteil', 'Ein gepoltes Bauteil (Elko, Diode oder LED) wurde falsch herum eingelötet. Vergleiche die Polung mit dem Schaltplan und setze das Teil richtig ein.', () => named(repStart('exnetz', [['reversed', 1]]), 'Reparatur: verpoltes Bauteil')],
    ['ex_rep_bruecke', 'Fehlersuche (Reparatur)', 'Reparatur: Lötbrücke im LED-Treiber', 'Zwischen zwei Pads sitzt ein Lotkontakt, die Schaltung zieht zu viel Strom. Finde die Brücke mit Messgerät und Lupe und sauge sie mit Entlötlitze weg.', () => named(repStart('exled', [['bridge', 1]]), 'Reparatur: Lötbrücke')],
    ['ex_rep_kalt', 'Fehlersuche (Reparatur)', 'Reparatur: kalte Lötstelle im LED-Treiber', 'Die Schaltung läuft nur, wenn du sie antippst: eine Lötstelle ist matt und körnig. Finde sie mit der Lupe und löte sie nach.', () => named(repStart('exled', [['cold', 1]]), 'Reparatur: kalte Lötstelle')],
    ['ex_rep_via', 'Fehlersuche (Reparatur)', 'Reparatur: gebrochenes Via im Netzteil', 'Eine Durchkontaktierung ist gebrochen, Oberseite und Unterseite sind dort getrennt. Miss beide Seiten getrennt und löte einen Draht durch das Via.', () => named(repStart('exnetz', [['viabreak', 1]]), 'Reparatur: gebrochenes Via')],
    ['ex_rep_wert', 'Fehlersuche (Reparatur)', 'Reparatur: falscher Widerstandswert im Verstärker', 'Ein Widerstand hat nicht den Wert aus der Stückliste, die Verstärkung stimmt nicht. Miss die Widerstände, finde den falschen und tausche ihn.', () => named(repStart('exopv', [['wrongvalue', 1]]), 'Reparatur: falscher Widerstandswert')]
  ];
  const examples = EX.map(e => ({ id: e[0], name: e[2], cat: e[1], desc: e[3], board: () => clone(e[4]()) }));

  /* ====================================================================== Antwortblatt (nur Browser) */
  function answerSheet(task, board, onChange) {
    if (typeof document === 'undefined' || !task || !Array.isArray(task.answer) || !board) return null;
    const el = document.createElement('div'); el.className = 'pcb-answer';
    const ans = () => { if (!board.answers || typeof board.answers !== 'object') board.answers = {}; return board.answers; };
    const put = (k, v) => { ans()[k] = v; if (typeof onChange === 'function') onChange(k, v, ans()); };
    task.answer.forEach(f => {
      const row = document.createElement('label'); row.style.cssText = 'display:block;margin:8px 0';
      const cap = document.createElement('span'); cap.textContent = f.label + (f.unit ? ' (' + f.unit + ')' : ''); cap.style.cssText = 'display:block;font-size:13px;margin-bottom:3px';
      row.appendChild(cap);
      if (f.type === 'select') {
        const s = document.createElement('select'); s.style.cssText = 'width:100%;min-height:44px;font-size:16px';
        const o0 = document.createElement('option'); o0.value = ''; o0.textContent = '– bitte wählen –'; s.appendChild(o0);
        f.options.forEach(o => { const op = document.createElement('option'); op.value = o[0]; op.textContent = o[1]; s.appendChild(op); });
        s.value = ans()[f.k] == null ? '' : ans()[f.k]; s.onchange = () => put(f.k, s.value); row.appendChild(s);
      } else if (f.type === 'order') {
        const box = document.createElement('div');
        const draw = () => {
          const refs = ans()[f.k] && ans()[f.k].length ? ans()[f.k].slice() : board.parts.map(p => p.ref); box.innerHTML = '';
          refs.forEach((r, i) => {
            const p = board.parts.find(q => q.ref === r) || {}, line = document.createElement('div'); line.style.cssText = 'display:flex;align-items:center;gap:6px;margin:3px 0';
            const t = document.createElement('span'); t.textContent = (i + 1) + '. ' + r + (p.value ? ' (' + p.value + ', ' + p.fp + ')' : ''); t.style.flex = '1';
            const mkb = (txt, d) => { const bt = document.createElement('button'); bt.type = 'button'; bt.textContent = txt; bt.style.cssText = 'min-width:44px;min-height:40px'; bt.disabled = i + d < 0 || i + d >= refs.length; bt.onclick = () => { const a = refs.slice(), x = a[i]; a[i] = a[i + d]; a[i + d] = x; put(f.k, a); draw(); }; return bt; };
            line.appendChild(t); line.appendChild(mkb('▲', -1)); line.appendChild(mkb('▼', 1)); box.appendChild(line);
          });
        };
        draw(); row.appendChild(box);
      } else {
        const inp = document.createElement('input'); inp.type = 'text'; inp.inputMode = 'decimal'; inp.style.cssText = 'width:100%;min-height:44px;font-size:16px';
        inp.value = ans()[f.k] == null ? '' : String(ans()[f.k]).replace('.', ','); inp.oninput = () => { const v = inp.value.trim(); put(f.k, v === '' ? '' : (isFinite(num(v)) ? num(v) : v)); };
        row.appendChild(inp);
      }
      el.appendChild(row);
    });
    return el;
  }

  /* ====================================================================== Ausführung, Selbsttest */
  const pctOf = rows => Math.round(100 * rows.filter(l => l.ok).length / Math.max(rows.length, 1));
  const PCB_TASKS = { tasks, run, answerSheet };
  root.PCB_DATA = { examples };
  root.PCB_TASKS = PCB_TASKS;
  root.TaskTest = async only => {
    const ids = only || tasks.map(t => t.id), out = [];
    for (const id of ids) {
      const t = tasks.find(x => x.id === id);
      if (!t) { out.push({ id, err: 'unbekannt' }); continue; }
      try {
        const a = pctOf(await PCB_TASKS.run(t, t.start())), L2 = await PCB_TASKS.run(t, t.sol());
        out.push({ id, pct: pctOf(L2), startPct: a, bad: L2.filter(x => !x.ok).map(x => x.text) });
      } catch (e) { out.push({ id, err: String(e) }); }
    }
    return out;
  };
  if (typeof module !== 'undefined') module.exports = { examples, tasks, run, board, DEF, BAKE, spike, ACID, acidStart, mk, planes, snapGrid, repStart, repSol, viasBad, mfgStart, reflip, setW, setCur, withAnswers, pruefWerte, rechne41, werte42, pctOf, roleOf, ipcFor, answerSheet };
